static bool buildPostWbRawFloatFromRggbBayer16( const uint16_t *bayer16,
                                                size_t bayerWords,
                                                int width,
                                                int height,
                                                int blackLevel,
                                                const double wbMultipliers[3],
                                                std::vector<float> *outRawFloat,
                                                QString *reason )
{
    if( !bayer16
     || !outRawFloat
     || !wbMultipliers
     || width <= 0
     || height <= 0 )
    {
        if( reason ) *reason = QStringLiteral("post-WB Bayer fallback input is invalid");
        return false;
    }
    if( wbMultipliers[0] <= 0.0
     || wbMultipliers[1] <= 0.0
     || wbMultipliers[2] <= 0.0 )
    {
        if( reason ) *reason = QStringLiteral("post-WB Bayer fallback WB multipliers are invalid");
        return false;
    }

    const size_t pixelCount =
        static_cast<size_t>( width ) * static_cast<size_t>( height );
    if( bayerWords < pixelCount )
    {
        if( reason ) *reason = QStringLiteral("post-WB Bayer fallback source is shorter than the frame geometry");
        return false;
    }

    try
    {
        outRawFloat->assign( pixelCount, 0.0f );
    }
    catch( const std::bad_alloc & )
    {
        if( reason ) *reason = QStringLiteral("post-WB Bayer fallback allocation failed");
        return false;
    }

    if( blackLevel < 1000 ) blackLevel = -1000;
    float *out = outRawFloat->data();
    for( int y = 0; y < height; ++y )
    {
        const size_t rowBase =
            static_cast<size_t>( y ) * static_cast<size_t>( width );
        for( int x = 0; x < width; ++x )
        {
            const size_t index = rowBase + static_cast<size_t>( x );
            const int channel =
                ((y & 1) == 0 && (x & 1) == 0)
                    ? 0
                    : (((y & 1) == 1 && (x & 1) == 1) ? 2 : 1);
            out[index] =
                static_cast<float>(
                    (static_cast<double>( bayer16[index] )
                        - static_cast<double>( blackLevel ))
                    * wbMultipliers[channel] );
        }
    }

    if( reason ) reason->clear();
    return true;
}

static void insertNullableDouble( QJsonObject *object,
                                  const QString &key,
                                  double value,
                                  bool valid )
{
    if( !object ) return;
    object->insert( key, valid ? QJsonValue( value ) : QJsonValue() );
}

static QString canonicalPlaybackFallbackReason( const QString &reason )
{
    const QString normalized = reason.trimmed().toLower();
    if( normalized.isEmpty() ) return QString();
    if( normalized.contains( QStringLiteral("backend") )
     || normalized.contains( QStringLiteral("unavailable") )
     || normalized.contains( QStringLiteral("not available") ) )
    {
        return QStringLiteral("backend_unavailable");
    }
    if( normalized.contains( QStringLiteral("capability") )
     || normalized.contains( QStringLiteral("gate") )
     || normalized.contains( QStringLiteral("admitted") ) )
    {
        return QStringLiteral("capability_gate_failed");
    }
    if( normalized.contains( QStringLiteral("unsupported") )
     || normalized.contains( QStringLiteral("processing") )
     || normalized.contains( QStringLiteral("settings") ) )
    {
        return QStringLiteral("unsupported_processing_stage");
    }
    if( normalized.contains( QStringLiteral("state") )
     || normalized.contains( QStringLiteral("snapshot") )
     || normalized.contains( QStringLiteral("config") )
     || normalized.contains( QStringLiteral("incomplete") )
     || normalized.contains( QStringLiteral("mismatch") ) )
    {
        return QStringLiteral("state_mismatch");
    }
    if( normalized.contains( QStringLiteral("vram") )
     || normalized.contains( QStringLiteral("memory") )
     || normalized.contains( QStringLiteral("alloc") ) )
    {
        return QStringLiteral("vram");
    }
    return QStringLiteral("other");
}

static QString playbackFallbackReasonToken(
    const QJsonObject &telemetry,
    GpuPlaybackPipelineStatus status,
    const QStringList &extraReasons = QStringList() )
{
    const bool noReadbackCandidate = telemetryBoolValue(
        telemetry,
        "gpu_playback_recon_texture_present_no_readback_candidate" );
    const bool textureCandidate = telemetryBoolValue(
        telemetry,
        "gpu_playback_recon_texture_present_candidate" );
    const bool textureRequested = telemetryBoolValue(
        telemetry,
        "gpu_playback_recon_texture_present_requested" );
    const bool reconAttempted = telemetryBoolValue(
        telemetry,
        "gpu_playback_recon_attempted" );

    bool demoted = false;
    if( noReadbackCandidate
     && status != GpuPlaybackPipelineStatus::GpuTextureNoReadback )
    {
        demoted = true;
    }
    else if( textureCandidate
          && status != GpuPlaybackPipelineStatus::GpuTextureReadback
          && status != GpuPlaybackPipelineStatus::GpuTextureNoReadback )
    {
        demoted = true;
    }
    else if( ( textureRequested || reconAttempted )
          && status == GpuPlaybackPipelineStatus::Cpu )
    {
        demoted = true;
    }

    if( !demoted ) return QString();

    QStringList reasons = extraReasons;
    reasons
        << telemetryStringValue(
               telemetry,
               "gpu_playback_recon_texture_present_no_readback_fallback_reason" )
        << telemetryStringValue(
               telemetry,
               "gpu_playback_recon_texture_present_fallback_reason" )
        << telemetryStringValue(
               telemetry,
               "gpu_amaze_texture_present_fallback_reason" );
    for( const QString &reason : reasons )
    {
        const QString token = canonicalPlaybackFallbackReason( reason );
        if( !token.isEmpty() ) return token;
    }
    return QStringLiteral("other");
}

static double playbackSampleStageValue( const QJsonObject &sample,
                                        const QStringList &keys,
                                        bool *valid )
{
    double total = 0.0;
    bool found = false;
    for( const QString &key : keys )
    {
        if( sample.contains( key ) )
        {
            total += sample.value( key ).toDouble();
            found = true;
        }
    }
    if( valid ) *valid = found;
    return total;
}

static void insertPlaybackStageSummaryFields( QJsonObject *sample )
{
    if( !sample ) return;

    bool valid = false;
    const double decodeMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("raw_uint16_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_decode_ms"),
        decodeMs,
        valid );

    const bool rawPrefetchHit =
        sample->value( QStringLiteral("raw_uint16_prefetch_hit") ).toBool();
    const bool processed8PrefetchHit =
        sample->value( QStringLiteral("processed8_prefetch_hit") ).toBool();
    insertNullableDouble(
        sample,
        QStringLiteral("stage_prefetch_ms"),
        0.0,
        rawPrefetchHit || processed8PrefetchHit );

    const double queueWaitMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("render_thread_queue_wait_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_queue_wait_ms"),
        queueWaitMs,
        valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_present_ui_signal_latency_ms"),
        queueWaitMs,
        valid );

    const double reconMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("llrawproc_total_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_recon_ms"),
        reconMs,
        valid );

    const double processMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("processed8_total_ms")
            << QStringLiteral("processed16_total_ms")
            << QStringLiteral("processing_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_process_ms"),
        processMs,
        valid );

    const double gpuUploadMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("gpu_playback_recon_texture_present_upload_ms")
            << QStringLiteral("gpu_bilinear_debayer_upload_ms")
            << QStringLiteral("gpu_amaze_debayer_upload_ms")
            << QStringLiteral("gpu_amaze_texture_present_upload_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_gpu_upload_ms"),
        gpuUploadMs,
        valid );

    bool drawTotalValid = false;
    const double drawTotalMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("draw_frame_ready_total_ms"),
        &drawTotalValid );
    const double fallbackPresentMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("draw_frame_ready_present_ms")
            << QStringLiteral("gpu_playback_recon_texture_present_total_ms")
            << QStringLiteral("gpu_amaze_texture_present_total_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_present_ms"),
        drawTotalValid ? drawTotalMs : fallbackPresentMs,
        drawTotalValid || valid );

    const double presentDrawMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("draw_frame_ready_image_ms")
            << QStringLiteral("draw_frame_ready_present_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_present_draw_ms"),
        presentDrawMs,
        valid );

    const double presentOverlaysScopesMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("draw_frame_ready_scopes_ms")
            << QStringLiteral("draw_frame_ready_overlay_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_present_overlays_scopes_ms"),
        presentOverlaysScopesMs,
        valid );

    const double presentSlotReleaseMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("draw_frame_ready_advance_ms"),
        &valid );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_present_slot_release_ms"),
        presentSlotReleaseMs,
        valid );

    bool renderTotalValid = false;
    const double renderTotalMs = playbackSampleStageValue(
        *sample,
        QStringList()
            << QStringLiteral("render_thread_total_ms"),
        &renderTotalValid );
    const bool cadenceValid =
        sample->contains( QStringLiteral("cadence_ms") )
        && sample->value( QStringLiteral("cadence_ms") ).isDouble();
    const double cadenceMs =
        cadenceValid
            ? sample->value( QStringLiteral("cadence_ms") ).toDouble()
            : 0.0;
    const double presentPacingMs =
        qMax( 0.0,
              cadenceMs
              - renderTotalMs
              - queueWaitMs
              - presentDrawMs
              - presentOverlaysScopesMs
              - presentSlotReleaseMs );
    insertNullableDouble(
        sample,
        QStringLiteral("stage_present_pacing_ms"),
        presentPacingMs,
        cadenceValid && renderTotalValid );

    const bool overheadValid =
        sample->contains(
            QStringLiteral("presentation_overhead_excluding_headless_color_ms") )
        || sample->contains( QStringLiteral("presentation_overhead_ms") );
    const double overheadMs =
        sample->contains(
            QStringLiteral("presentation_overhead_excluding_headless_color_ms") )
            ? sample->value(
                  QStringLiteral(
                      "presentation_overhead_excluding_headless_color_ms" ) )
                  .toDouble()
            : sample->value( QStringLiteral("presentation_overhead_ms") )
                  .toDouble();
    insertNullableDouble(
        sample,
        QStringLiteral("stage_presentation_overhead_ms"),
        overheadMs,
        overheadValid );
}

static double sortedPercentile( QVector<double> values, double percentile )
{
    if( values.isEmpty() ) return 0.0;
    std::sort( values.begin(), values.end() );
    const int index =
        qBound( 0,
                static_cast<int>( ( values.size() - 1 ) * percentile ),
                values.size() - 1 );
    return values.at( index );
}

static QString suggestedOptimizationForBottleneck( const QString &bottleneck )
{
    if( bottleneck == QStringLiteral("decode-bound") )
        return QStringLiteral("parallelize_lj92_decode");
    if( bottleneck == QStringLiteral("prefetch-bound") )
        return QStringLiteral("deepen_prefetch_window");
    if( bottleneck == QStringLiteral("recon-bound") )
        return QStringLiteral("optimize_dual_iso_recon");
    if( bottleneck == QStringLiteral("process-bound") )
        return QStringLiteral("move_processing_to_gpu_or_fast_subset");
    if( bottleneck == QStringLiteral("gpu-upload-bound") )
        return QStringLiteral("reduce_gpu_upload_or_enable_no_readback");
    if( bottleneck == QStringLiteral("queue-wait-bound") )
        return QStringLiteral("reduce_render_queue_wait_or_present_signal_latency");
    if( bottleneck == QStringLiteral("present-bound") )
        return QStringLiteral("reduce_present_overhead");
    if( bottleneck == QStringLiteral("present-draw-bound") )
        return QStringLiteral("reduce_present_draw_overhead");
    if( bottleneck == QStringLiteral("frame-pacing-bound") )
        return QStringLiteral("stabilize_playback_frame_pacing");
    if( bottleneck == QStringLiteral("presentation-overhead-bound") )
        return QStringLiteral("reduce_ui_presentation_overhead");
    if( bottleneck == QStringLiteral("compress-bound") )
        return QStringLiteral("parallelize_or_offload_dng_compress");
    if( bottleneck == QStringLiteral("write-bound") )
        return QStringLiteral("increase_async_writer_depth_or_storage_bandwidth");
    return QStringLiteral("collect_more_stage_samples");
}

static QJsonObject buildStageBottleneckSummary(
    const QJsonArray &frames,
    const QList<QPair<QString, QString>> &stages )
{
    QJsonObject stageSummary;
    QString limitingStage = QStringLiteral("unknown");
    double limitingMedian = 0.0;
    double limitingP95 = 0.0;

    for( const QPair<QString, QString> &stage : stages )
    {
        QVector<double> values;
        for( const QJsonValue &value : frames )
        {
            const QJsonObject sample = value.toObject();
            const QJsonValue stageValue = sample.value( stage.second );
            if( stageValue.isDouble() )
            {
                values.append( stageValue.toDouble() );
            }
        }
        if( values.isEmpty() ) continue;

        const double median = sortedPercentile( values, 0.50 );
        const double p95 = sortedPercentile( values, 0.95 );
        QJsonObject oneStage;
        oneStage.insert( QStringLiteral("samples"), values.size() );
        oneStage.insert( QStringLiteral("median_ms"), median );
        oneStage.insert( QStringLiteral("p95_ms"), p95 );
        stageSummary.insert( stage.first, oneStage );
        if( limitingStage == QStringLiteral("unknown") || median > limitingMedian )
        {
            limitingStage = stage.first;
            limitingMedian = median;
            limitingP95 = p95;
        }
    }

    QJsonObject bottleneck;
    bottleneck.insert( QStringLiteral("schema"),
                       QStringLiteral("mlvapp.bottleneck-rollup.v1") );
    bottleneck.insert( QStringLiteral("limiting_stage"), limitingStage );
    bottleneck.insert( QStringLiteral("median_ms"), limitingMedian );
    bottleneck.insert( QStringLiteral("p95_ms"), limitingP95 );
    bottleneck.insert( QStringLiteral("suggested_optimization"),
                       suggestedOptimizationForBottleneck( limitingStage ) );
    bottleneck.insert( QStringLiteral("stages"), stageSummary );
    return bottleneck;
}

static void incrementJsonCounter( QJsonObject *object, const QString &key )
{
    if( !object ) return;
    object->insert( key, object->value( key ).toInt() + 1 );
}

static QStringList gpuPlaybackReconAsyncH2dTelemetryKeys()
{
    return QStringList()
        << QStringLiteral("gpu_playback_recon_async_h2d_env_enabled")
        << QStringLiteral("gpu_playback_recon_async_h2d_available")
        << QStringLiteral("gpu_playback_recon_async_h2d_accepted")
        << QStringLiteral("gpu_playback_recon_async_h2d_used")
        << QStringLiteral("gpu_playback_recon_async_h2d_exact_match")
        << QStringLiteral(
               "gpu_playback_recon_async_h2d_submitted_while_prior_run_active" )
        << QStringLiteral("gpu_playback_recon_async_h2d_ready_before_run")
        << QStringLiteral("gpu_playback_recon_async_h2d_host_staging_ms")
        << QStringLiteral("gpu_playback_recon_async_h2d_upload_ms")
        << QStringLiteral("gpu_playback_recon_async_h2d_upload_wait_ms");
}

static QJsonObject gpuPlaybackReconAsyncH2dTelemetry(
    const QJsonObject &telemetry )
{
    QJsonObject result;
    const QStringList keys = gpuPlaybackReconAsyncH2dTelemetryKeys();
    for( const QString &key : keys )
    {
        const auto it = telemetry.constFind( key );
        if( it != telemetry.constEnd() ) result.insert( key, it.value() );
    }
    return result;
}

static QJsonObject buildAsyncH2dRollup(
    const QJsonObject &booleanSampleCounts,
    const QJsonObject &booleanTrueCounts,
    const QJsonObject &timingSums,
    const QJsonObject &timingMaxima,
    const QJsonObject &timingSampleCounts )
{
    QJsonObject rollup;
    const QStringList keys = gpuPlaybackReconAsyncH2dTelemetryKeys();
    for( const QString &key : keys )
    {
        const int booleanSamples = booleanSampleCounts.value( key ).toInt();
        const int timingSamples = timingSampleCounts.value( key ).toInt();
        QJsonObject field;
        if( booleanSamples > 0 )
        {
            const int trueFrames = booleanTrueCounts.value( key ).toInt();
            field.insert( QStringLiteral("samples"), booleanSamples );
            field.insert( QStringLiteral("true_frames"), trueFrames );
            field.insert( QStringLiteral("false_frames"),
                          booleanSamples - trueFrames );
        }
        else if( timingSamples > 0 )
        {
            field.insert( QStringLiteral("samples"), timingSamples );
            field.insert( QStringLiteral("mean_ms"),
                          timingSums.value( key ).toDouble()
                              / static_cast<double>( timingSamples ) );
            field.insert( QStringLiteral("max_ms"),
                          timingMaxima.value( key ).toDouble() );
        }
        if( !field.isEmpty() ) rollup.insert( key, field );
    }
    return rollup;
}

static QJsonObject buildPlaybackProfileSummary( const QJsonArray &frames )
{
    QJsonObject pipelineCounts;
    pipelineCounts.insert( QStringLiteral("cpu"), 0 );
    pipelineCounts.insert( QStringLiteral("gpu_preview"), 0 );
    pipelineCounts.insert( QStringLiteral("gpu_recon_readback"), 0 );
    pipelineCounts.insert( QStringLiteral("gpu_texture_readback"), 0 );
    pipelineCounts.insert( QStringLiteral("gpu_texture_no_readback"), 0 );

    QJsonObject fallbackReasonHistogram;
    QJsonObject asyncH2dBooleanTrueCounts;
    QJsonObject asyncH2dBooleanSampleCounts;
    QJsonObject asyncH2dTimingSums;
    QJsonObject asyncH2dTimingMaxima;
    QJsonObject asyncH2dTimingSampleCounts;
    int fallbackCount = 0;
    for( const QJsonValue &value : frames )
    {
        const QJsonObject sample = value.toObject();
        const QString pipeline =
            sample.value( QStringLiteral("playback_pipeline") ).toString(
                QStringLiteral("cpu") );
        incrementJsonCounter( &pipelineCounts, pipeline );
        const QString fallbackReason =
            sample.value( QStringLiteral("fallback_reason") ).toString();
        if( !fallbackReason.isEmpty() )
        {
            ++fallbackCount;
            incrementJsonCounter( &fallbackReasonHistogram, fallbackReason );
        }
        const QJsonObject asyncH2d =
            gpuPlaybackReconAsyncH2dTelemetry( sample );
        for( auto it = asyncH2d.constBegin(); it != asyncH2d.constEnd(); ++it )
        {
            if( it.value().isBool() )
            {
                incrementJsonCounter( &asyncH2dBooleanSampleCounts, it.key() );
                if( it.value().toBool() )
                    incrementJsonCounter( &asyncH2dBooleanTrueCounts, it.key() );
            }
            else if( it.value().isDouble() )
            {
                const double timingMs = it.value().toDouble();
                asyncH2dTimingSums.insert(
                    it.key(),
                    asyncH2dTimingSums.value( it.key() ).toDouble() + timingMs );
                asyncH2dTimingMaxima.insert(
                    it.key(),
                    qMax( asyncH2dTimingMaxima.value( it.key() ).toDouble(),
                          timingMs ) );
                incrementJsonCounter( &asyncH2dTimingSampleCounts, it.key() );
            }
        }
    }

    const QJsonObject asyncH2dRollup = buildAsyncH2dRollup(
        asyncH2dBooleanSampleCounts,
        asyncH2dBooleanTrueCounts,
        asyncH2dTimingSums,
        asyncH2dTimingMaxima,
        asyncH2dTimingSampleCounts );

    QJsonObject summary;
    summary.insert( QStringLiteral("schema"),
                    QStringLiteral("mlvapp.playback-profile-summary.v1") );
    summary.insert( QStringLiteral("sample_count"), frames.size() );
    summary.insert( QStringLiteral("pipeline_counts"), pipelineCounts );
    summary.insert( QStringLiteral("fallback_count"), fallbackCount );
    summary.insert( QStringLiteral("fallback_reason_histogram"),
                    fallbackReasonHistogram );
    summary.insert( QStringLiteral("gpu_playback_recon_async_h2d"),
                    asyncH2dRollup );
    summary.insert( QStringLiteral("bottleneck"),
                    buildStageBottleneckSummary(
                        frames,
                        QList<QPair<QString, QString>>()
                            << qMakePair( QStringLiteral("decode-bound"),
                                          QStringLiteral("stage_decode_ms") )
                            << qMakePair( QStringLiteral("prefetch-bound"),
                                          QStringLiteral("stage_prefetch_ms") )
                            << qMakePair( QStringLiteral("recon-bound"),
                                          QStringLiteral("stage_recon_ms") )
                            << qMakePair( QStringLiteral("process-bound"),
                                          QStringLiteral("stage_process_ms") )
                            << qMakePair( QStringLiteral("gpu-upload-bound"),
                                          QStringLiteral("stage_gpu_upload_ms") )
                            << qMakePair( QStringLiteral("queue-wait-bound"),
                                          QStringLiteral("stage_queue_wait_ms") )
                            << qMakePair( QStringLiteral("present-bound"),
                                          QStringLiteral("stage_present_ms") )
                            << qMakePair( QStringLiteral("present-draw-bound"),
                                          QStringLiteral("stage_present_draw_ms") )
                            << qMakePair( QStringLiteral("frame-pacing-bound"),
                                          QStringLiteral("stage_present_pacing_ms") )
                            << qMakePair( QStringLiteral("presentation-overhead-bound"),
                                          QStringLiteral("stage_presentation_overhead_ms") ) ) );
    return summary;
}

static bool perfFieldLogEnabled()
{
    return CrashForensics::performanceFieldLogRuntimeEnabled();
}

static QString perfFieldLogPath()
{
    return CrashForensics::performanceFieldLogPath();
}

static void appendPerfFieldLogLine( const QJsonObject &line )
{
    if( !perfFieldLogEnabled() ) return;
    const QString path = perfFieldLogPath();
    if( path.isEmpty() ) return;
    QDir().mkpath( QFileInfo( path ).absolutePath() );
    QFile file( path );
    if( !file.open( QIODevice::WriteOnly | QIODevice::Append | QIODevice::Text ) )
    {
        qWarning().noquote()
            << QStringLiteral("perf_field_log_append_failed path=%1").arg( path );
        return;
    }
    file.write( QJsonDocument( line ).toJson( QJsonDocument::Compact ) );
    file.write( "\n" );
}

static void logInteractionEvent( const QString &event,
                                 const QString &details = QString(),
                                 bool traceOnly = false )
{
    if( traceOnly && !interactiveTraceEnabled() ) return;

    QString message = QStringLiteral("interaction_trace event=%1").arg( event );
    if( !details.isEmpty() ) message += QLatin1Char(' ') + details;
    qInfo().noquote() << message;
}

enum class LookAssistScene
{
    Night,
    ArtificialLights,
    Shade,
    BrightSun
};

struct LookAssistStats
{
    double median = 0.0;
    double p05 = 0.0;
    double p95 = 0.0;
    double p99 = 0.0;
    double clipLow = 0.0;
    double clipHigh = 0.0;
    double dynamicRange = 0.0;
    double medianR = 0.0;
    double medianG = 0.0;
    double medianB = 0.0;
    double balanceR = 0.0;
    double balanceG = 0.0;
    double balanceB = 0.0;
    int balanceSamples = 0;
    double visibleMeanR = 0.0;
    double visibleMeanG = 0.0;
    double visibleMeanB = 0.0;
    int visibleSamples = 0;
    double greenArtifactRatio = 0.0;
    double greenArtifactMeanAxis = 0.0;
    int greenArtifactSamples = 0;
};

struct LookAssistPreset
{
    int exposure = 0;
    int contrast = 0;
    int pivot = 75;
    int shadows = 0;
    int highlights = 0;
    int vibrance = 0;
    int temperatureDelta = 0;
    int tintDelta = 0;
};

struct LookAssistAutoWhiteBalancePatch
{
    bool valid = false;
    int thumbnailX = -1;
    int thumbnailY = -1;
    int rawX = -1;
    int rawY = -1;
    double luma = 0.0;
    double chroma = 0.0;
    double greenAxis = 0.0;
    double blueAmberAxis = 0.0;
    double score = -1.0e9;
};

static QString lookAssistSceneName( LookAssistScene scene )
{
    switch( scene )
    {
    case LookAssistScene::Night:
        return QStringLiteral("night");
    case LookAssistScene::ArtificialLights:
        return QStringLiteral("artificial-lights");
    case LookAssistScene::Shade:
        return QStringLiteral("shade");
    case LookAssistScene::BrightSun:
        return QStringLiteral("bright-sun");
    }
    return QStringLiteral("unknown");
}

static double lookAssistPercentile( const int *histogram, int totalSamples, double fraction )
{
    if( !histogram || totalSamples <= 0 ) return 0.0;

    const int target = qBound( 1, (int)ceil( fraction * totalSamples ), totalSamples );
    int cumulative = 0;
    for( int i = 0; i < 256; ++i )
    {
        cumulative += histogram[i];
        if( cumulative >= target ) return (double)i;
    }
    return 255.0;
}

static LookAssistStats analyzeLookAssistThumbnail( const unsigned char *rgb, int width, int height )
{
    LookAssistStats stats;
    if( !rgb || width <= 0 || height <= 0 ) return stats;

    int histogram[256] = { 0 };
    int histogramR[256] = { 0 };
    int histogramG[256] = { 0 };
    int histogramB[256] = { 0 };
    int balanceHistogramR[256] = { 0 };
    int balanceHistogramG[256] = { 0 };
    int balanceHistogramB[256] = { 0 };
    const int totalSamples = width * height;
    double visibleRTotal = 0.0;
    double visibleGTotal = 0.0;
    double visibleBTotal = 0.0;
    double greenArtifactAxisTotal = 0.0;

    for( int i = 0; i < totalSamples; ++i )
    {
        const int base = i * 3;
        const int r = rgb[base + 0];
        const int g = rgb[base + 1];
        const int b = rgb[base + 2];
        const int luma = qBound( 0, ( 54 * r + 183 * g + 19 * b ) >> 8, 255 );
        histogram[luma]++;
        histogramR[r]++;
        histogramG[g]++;
        histogramB[b]++;

        const int maxChannel = qMax( r, qMax( g, b ) );
        const int minChannel = qMin( r, qMin( g, b ) );
        const int saturationProxy = maxChannel - minChannel;
        const double greenAxis = (double)g - ( ( (double)r + (double)b ) * 0.5 );
        if( luma >= 12 )
        {
            visibleRTotal += (double)r;
            visibleGTotal += (double)g;
            visibleBTotal += (double)b;
            stats.visibleSamples++;
        }
        if( luma >= 12
         && g >= 30
         && greenAxis >= 25.0 )
        {
            greenArtifactAxisTotal += greenAxis;
            stats.greenArtifactSamples++;
        }
        if( luma >= 20
         && luma <= 230
         && saturationProxy <= qMax( 14, luma / 5 ) )
        {
            balanceHistogramR[r]++;
            balanceHistogramG[g]++;
            balanceHistogramB[b]++;
            stats.balanceSamples++;
        }
    }

    stats.median = lookAssistPercentile( histogram, totalSamples, 0.50 );
    stats.p05 = lookAssistPercentile( histogram, totalSamples, 0.05 );
    stats.p95 = lookAssistPercentile( histogram, totalSamples, 0.95 );
    stats.p99 = lookAssistPercentile( histogram, totalSamples, 0.99 );
    stats.dynamicRange = stats.p95 - stats.p05;
    stats.medianR = lookAssistPercentile( histogramR, totalSamples, 0.50 );
    stats.medianG = lookAssistPercentile( histogramG, totalSamples, 0.50 );
    stats.medianB = lookAssistPercentile( histogramB, totalSamples, 0.50 );

    if( stats.balanceSamples >= qMax( 32, totalSamples / 100 ) )
    {
        stats.balanceR = lookAssistPercentile( balanceHistogramR, stats.balanceSamples, 0.50 );
        stats.balanceG = lookAssistPercentile( balanceHistogramG, stats.balanceSamples, 0.50 );
        stats.balanceB = lookAssistPercentile( balanceHistogramB, stats.balanceSamples, 0.50 );
    }
    else
    {
        stats.balanceR = stats.medianR;
        stats.balanceG = stats.medianG;
        stats.balanceB = stats.medianB;
    }
    if( stats.visibleSamples > 0 )
    {
        stats.visibleMeanR = visibleRTotal / (double)stats.visibleSamples;
        stats.visibleMeanG = visibleGTotal / (double)stats.visibleSamples;
        stats.visibleMeanB = visibleBTotal / (double)stats.visibleSamples;
        stats.greenArtifactRatio =
            (double)stats.greenArtifactSamples / (double)stats.visibleSamples;
    }
    if( stats.greenArtifactSamples > 0 )
    {
        stats.greenArtifactMeanAxis =
            greenArtifactAxisTotal / (double)stats.greenArtifactSamples;
    }

    int clipLow = histogram[0] + histogram[1] + histogram[2] + histogram[3];
    int clipHigh = histogram[252] + histogram[253] + histogram[254] + histogram[255];
    stats.clipLow = (double)clipLow / (double)totalSamples;
    stats.clipHigh = (double)clipHigh / (double)totalSamples;
    return stats;
}

static LookAssistScene classifyLookAssistScene( const LookAssistStats &stats )
{
    if( stats.p95 >= 220.0 || stats.clipHigh > 0.015 )
        return LookAssistScene::BrightSun;

    if( stats.median < 60.0 )
    {
        if( stats.clipHigh > 0.006 || stats.p99 >= 236.0 || stats.p95 >= 185.0 )
            return LookAssistScene::ArtificialLights;
        return LookAssistScene::Night;
    }

    return LookAssistScene::Shade;
}

static bool lookAssistIsFloorLiftedNightThumbnail( LookAssistScene scene, const LookAssistStats &stats )
{
    // Settled Dual ISO/raw preview paths can lift near-black thumbnails to a
    // flat floor around 32, even when the scene still needs night rescue.
    return scene == LookAssistScene::Night &&
           stats.median >= 24.0 &&
           stats.p05 >= 18.0 &&
           stats.p95 <= 70.0 &&
           stats.dynamicRange <= 24.0;
}

static bool lookAssistIsFlatNoiseFloorThumbnail( LookAssistScene scene, const LookAssistStats &stats )
{
    return scene == LookAssistScene::Night
        && stats.median <= 34.0
        && stats.p05 <= 34.0
        && stats.p95 <= 34.0
        && stats.p99 <= 34.0
        && ( stats.p99 - stats.p05 ) <= 2.0;
}

static int lookAssistExposureForTarget( double sourceValue, double targetValue, int fallback )
{
    if( sourceValue <= 1.0 || targetValue <= 1.0 ) return fallback;
    return (int)qRound( log( targetValue / sourceValue ) / log( 2.0 ) * 100.0 );
}

static bool lookAssistHasNeutralBalanceSamples( const LookAssistStats &stats )
{
    return stats.balanceSamples >= 32
        && stats.balanceR > 0.0
        && stats.balanceG > 0.0
        && stats.balanceB > 0.0;
}

static int lookAssistAutoTintCap( LookAssistScene scene, bool processedFloorLiftedBalance )
{
    (void)processedFloorLiftedBalance;
    if( scene == LookAssistScene::BrightSun ) return 8;
    return 22;
}

static LookAssistAutoWhiteBalancePatch findLookAssistAutoWhiteBalancePatch(
        const unsigned char *rgb,
        int width,
        int height,
        int downscaleFactor,
        int rawWidth,
        int rawHeight )
{
    LookAssistAutoWhiteBalancePatch best;
    if( !rgb
     || width <= 0
     || height <= 0
     || downscaleFactor <= 0
     || rawWidth <= 0
     || rawHeight <= 0 )
    {
        return best;
    }

    const int edgeMarginX = qMax( 1, width / 80 );
    const int edgeMarginY = qMax( 1, height / 80 );
    for( int y = edgeMarginY; y < height - edgeMarginY; ++y )
    {
        for( int x = edgeMarginX; x < width - edgeMarginX; ++x )
        {
            const int base = ( y * width + x ) * 3;
            const int r = rgb[base + 0];
            const int g = rgb[base + 1];
            const int b = rgb[base + 2];
            const int maxChannel = qMax( r, qMax( g, b ) );
            const int minChannel = qMin( r, qMin( g, b ) );
            const double chroma = (double)( maxChannel - minChannel );
            const double luma = ( 54.0 * r + 183.0 * g + 19.0 * b ) / 256.0;
            if( luma < 70.0 || luma > 220.0 ) continue;
            if( chroma > qMax( 10.0, luma * 0.16 ) ) continue;

            const double greenAxis = (double)g - ( ( (double)r + (double)b ) * 0.5 );
            const double blueAmberAxis = (double)b - (double)r;
            if( greenAxis > 14.0 ) continue;
            if( fabs( blueAmberAxis ) > 30.0 ) continue;

            const double score =
                luma * 0.75
                - chroma * 1.6
                - qMax( 0.0, greenAxis ) * 2.8
                - fabs( blueAmberAxis ) * 0.4;
            if( !best.valid || score > best.score )
            {
                best.valid = true;
                best.thumbnailX = x;
                best.thumbnailY = y;
                best.rawX = qBound( 0, x * downscaleFactor + downscaleFactor / 2, rawWidth - 1 );
                best.rawY = qBound( 0, y * downscaleFactor + downscaleFactor / 2, rawHeight - 1 );
                best.luma = luma;
                best.chroma = chroma;
                best.greenAxis = greenAxis;
                best.blueAmberAxis = blueAmberAxis;
                best.score = score;
            }
        }
    }
    return best;
}

static bool lookAssistAutoWhiteBalanceSolutionIsStable(
        const LookAssistAutoWhiteBalancePatch &patch,
        int baseTemperature,
        int baseTint,
        int candidateTemperature,
        int candidateTint )
{
    if( !patch.valid ) return false;

    const int temperatureDelta = candidateTemperature - baseTemperature;
    const int tintDelta = candidateTint - baseTint;
    const bool extremeGreenCorrection =
        candidateTint <= -34
        && temperatureDelta <= -1200
        && patch.luma >= 205.0
        && patch.chroma >= 12.0
        && fabs( patch.blueAmberAxis ) >= 14.0;
    if( extremeGreenCorrection )
    {
        return false;
    }

    const bool hardGreenClampFromBrightNeutralPatch =
        candidateTint <= -34
        && patch.luma >= 210.0
        && patch.chroma <= 6.0
        && qAbs( temperatureDelta ) <= 1000;
    if( hardGreenClampFromBrightNeutralPatch )
    {
        return false;
    }

    const bool hardGreenClampFromLowChromaMidtonePatch =
        candidateTint <= -34
        && patch.luma >= 70.0
        && patch.luma <= 160.0
        && patch.chroma <= 8.0
        && qAbs( temperatureDelta ) <= 1200;
    if( hardGreenClampFromLowChromaMidtonePatch )
    {
        return false;
    }

    const bool implausibleDualAxisSwing =
        fabs( static_cast<double>( tintDelta ) ) >= 34.0
        && qAbs( temperatureDelta ) >= 1800
        && patch.chroma >= 12.0
        && patch.luma >= 200.0;
    return !implausibleDualAxisSwing;
}

static double lookAssistAutoWhiteBalanceDampingFactor(
        const LookAssistAutoWhiteBalancePatch &patch,
        int baseTemperature,
        int baseTint,
        int candidateTemperature,
        int candidateTint,
        LookAssistScene scene )
{
    if( !patch.valid ) return 1.0;

    const int temperatureDelta = candidateTemperature - baseTemperature;
    const int tintDelta = candidateTint - baseTint;
    double factor = 1.0;

    if( patch.chroma >= 14.0 && qAbs( temperatureDelta ) >= 900 )
    {
        factor = qMin( factor, 0.70 );
    }
    if( patch.chroma >= 10.0 && qAbs( temperatureDelta ) >= 1200 )
    {
        factor = qMin( factor, 0.65 );
    }
    if( patch.chroma >= 10.0 && qAbs( tintDelta ) >= 24 )
    {
        factor = qMin( factor, 0.75 );
    }
    if( scene == LookAssistScene::Night
     && patch.luma < 150.0
     && qAbs( temperatureDelta ) >= 1000 )
    {
        factor = qMin( factor, 0.70 );
    }
    return factor;
}

static QString lookAssistColorCastWarning(
        bool postColorStatsValid,
        const LookAssistStats &postColorStats,
        double postVisibleGreenAxis,
        int finalTemperature,
        double postBlueAmberAxis )
{
    if( postColorStatsValid )
    {
        if( postColorStats.greenArtifactRatio >= 0.10
         && postColorStats.greenArtifactMeanAxis >= 25.0 )
        {
            return QStringLiteral("localized-green-artifact");
        }
        if( postVisibleGreenAxis >= 8.0 )
        {
            return QStringLiteral("global-green-cast");
        }
        if( postVisibleGreenAxis <= -8.0 )
        {
            return QStringLiteral("global-magenta-cast");
        }
        if( finalTemperature <= 5200 && postBlueAmberAxis >= 4.0 )
        {
            return QStringLiteral("cool-blue-cast");
        }
        if( finalTemperature >= 6800 && postBlueAmberAxis <= -4.0 )
        {
            return QStringLiteral("warm-amber-cast");
        }
    }
    return QStringLiteral("none");
}

static bool lookAssistColorCastShouldFailClosed( const QString &warning,
                                                 double greenArtifactRatio,
                                                 double greenArtifactMeanAxis,
                                                 double visibleGreenAxis,
                                                 bool postAppliedStats )
{
    if( warning == QStringLiteral("rejected-unstable-floor-lifted") )
    {
        return true;
    }
    if( warning == QStringLiteral("processed-floor-lifted-awb-risk") )
    {
        return true;
    }
    if( warning == QStringLiteral("processed-floor-lifted-post-invalid") )
    {
        return true;
    }
    if( warning == QStringLiteral("global-green-cast")
     || warning == QStringLiteral("global-magenta-cast") )
    {
        return postAppliedStats;
    }
    if( warning == QStringLiteral("localized-green-artifact") )
    {
        if( !postAppliedStats )
        {
            return false;
        }
        return visibleGreenAxis >= 14.0
            || ( greenArtifactRatio >= 0.28 && greenArtifactMeanAxis >= 42.0 );
    }
    return false;
}

static bool lookAssistProcessedFloorLiftedAutoWhiteBalanceShouldFailClosed(
        bool floorLifted,
        bool useProcessedColorStats,
        bool autoWhiteBalanceValid,
        int baseTemperature,
        int baseTint,
        int finalTemperature,
        int finalTint )
{
    if( !floorLifted || !useProcessedColorStats || !autoWhiteBalanceValid )
    {
        return false;
    }

    const int temperatureDelta = finalTemperature - baseTemperature;
    const int tintDelta = finalTint - baseTint;
    return temperatureDelta <= -900
        || tintDelta <= -24
        || finalTint <= -24;
}

static bool lookAssistProcessedFloorLiftedPostInvalidShouldFailClosed(
        bool floorLifted,
        bool canAnalyzeProcessedColor,
        bool postColorStatsValid,
        bool chromaSmoothAutoApplied,
        int rawWhite,
        int originalRawWhite )
{
    return floorLifted
        && canAnalyzeProcessedColor
        && !postColorStatsValid
        && chromaSmoothAutoApplied
        && originalRawWhite > 0
        && rawWhite > 0
        && rawWhite <= originalRawWhite;
}

static int lookAssistDisplayTargetMedianForScene( LookAssistScene scene )
{
    switch( scene )
    {
    case LookAssistScene::Night:            return 64;
    case LookAssistScene::ArtificialLights: return 82;
    case LookAssistScene::Shade:            return 96;
    case LookAssistScene::BrightSun:        return 110;
    }
    return 88;
}

static LookAssistPreset presetForLookAssistScene( LookAssistScene scene,
                                                  const LookAssistStats &stats,
                                                  const LookAssistStats *colorStats = nullptr,
                                                  const LookAssistStats *displayStats = nullptr )
{
    LookAssistPreset preset;
    int targetMedian = 110;

    switch( scene )
    {
    case LookAssistScene::Night:
        targetMedian = 94;
        preset.contrast = 8;
        preset.pivot = 46;
        preset.shadows = 28;
        preset.highlights = -18;
        preset.vibrance = 3;
        break;
    case LookAssistScene::ArtificialLights:
        targetMedian = 96;
        preset.contrast = 10;
        preset.pivot = 50;
        preset.shadows = 10;
        preset.highlights = -24;
        preset.vibrance = 2;
        break;
    case LookAssistScene::Shade:
        targetMedian = 112;
        preset.contrast = 9;
        preset.pivot = 55;
        preset.shadows = 12;
        preset.highlights = -12;
        preset.vibrance = 5;
        break;
    case LookAssistScene::BrightSun:
        targetMedian = 118;
        preset.contrast = 6;
        preset.pivot = 60;
        preset.shadows = 4;
        preset.highlights = -30;
        preset.vibrance = 0;
        break;
    }

    const bool floorLiftedNightThumbnail =
        lookAssistIsFloorLiftedNightThumbnail( scene, stats );
    const bool flatNoiseFloorThumbnail =
        lookAssistIsFlatNoiseFloorThumbnail( scene, stats );
    const double sourceMedian = floorLiftedNightThumbnail
        ? qMax( 2.0, ( stats.median - stats.p05 ) + 2.0 )
        : qMax( 1.0, stats.median );
    int exposure = lookAssistExposureForTarget( sourceMedian, targetMedian, 0 );
    int maxExposure = 180;
    int minExposure = -140;
    double p95Ceiling = 172.0;
    double p99Ceiling = 218.0;
    if( scene == LookAssistScene::Night )
    {
        maxExposure = ( stats.p99 < 55.0 ) ? 380 : 260;
        if( flatNoiseFloorThumbnail )
            maxExposure = qMin( maxExposure, 170 );
        minExposure = -40;
        p95Ceiling = floorLiftedNightThumbnail ? 124.0 : 142.0;
        p99Ceiling = floorLiftedNightThumbnail ? 160.0 : 188.0;
    }
    else if( scene == LookAssistScene::ArtificialLights )
    {
        maxExposure = 220;
        minExposure = -120;
        p95Ceiling = 150.0;
        p99Ceiling = 194.0;
    }
    else if( scene == LookAssistScene::BrightSun )
    {
        maxExposure = 0;
        minExposure = -180;
        p95Ceiling = 146.0;
        p99Ceiling = 184.0;
    }

    int highlightCap = maxExposure;
    highlightCap = qMin( highlightCap, lookAssistExposureForTarget( stats.p95, p95Ceiling, highlightCap ) );
    highlightCap = qMin( highlightCap, lookAssistExposureForTarget( stats.p99, p99Ceiling, highlightCap ) );
    if( stats.clipHigh > 0.002 )
        highlightCap = qMin( highlightCap, 0 );
    exposure = qMin( exposure, highlightCap );

    exposure = qBound( minExposure, exposure, maxExposure );
    if( scene == LookAssistScene::BrightSun )
        exposure = qMin( exposure, 0 );
    if( scene == LookAssistScene::Night )
        exposure = qMax( exposure, 0 );

    if( displayStats != nullptr && displayStats->median > 0.0 )
    {
        const int displayTarget = lookAssistDisplayTargetMedianForScene( scene );
        int displayExposure = lookAssistExposureForTarget(
            qMax( 1.0, displayStats->median ), (double)displayTarget, 0 );
        const int displayCap = lookAssistExposureForTarget(
            qMax( 1.0, displayStats->p99 ), 440.0, 400 );
        displayExposure = qMin( displayExposure, displayCap );
        exposure = qBound( -120, displayExposure, 380 );
    }

    preset.exposure = exposure;

    if( stats.dynamicRange < 100.0 ) preset.contrast += 6;
    else if( stats.dynamicRange < 130.0 ) preset.contrast += 3;
    else if( stats.dynamicRange > 180.0 ) preset.contrast -= 4;

    if( stats.p05 < 18.0 ) preset.shadows += 8;
    if( stats.p05 < 12.0 ) preset.shadows += 6;
    if( floorLiftedNightThumbnail ) preset.shadows = qMax( preset.shadows, 32 );
    if( stats.clipHigh > 0.010 ) preset.highlights -= 8;
    if( stats.clipHigh > 0.020 ) preset.highlights -= 8;
    const double exposureScale = pow( 2.0, exposure / 100.0 );
    const double projectedP95 = stats.p95 * exposureScale;
    const double projectedP99 = stats.p99 * exposureScale;
    if( projectedP95 > p95Ceiling - 2.0 ) preset.highlights -= 8;
    if( projectedP99 > p99Ceiling - 2.0 ) preset.highlights -= 8;

    if( scene == LookAssistScene::BrightSun )
    {
        preset.shadows = qMin( preset.shadows, 6 );
        preset.vibrance = qMin( preset.vibrance, 2 );
    }

    const LookAssistStats &balanceStats = colorStats ? *colorStats : stats;
    const bool processedFloorLiftedBalance = colorStats && floorLiftedNightThumbnail;
    const bool lowSignalFloorLiftedBalance =
        processedFloorLiftedBalance &&
        balanceStats.median > 0.0 &&
        balanceStats.median < 32.0;
    const double magentaGreenAxis = balanceStats.balanceG - ( ( balanceStats.balanceR + balanceStats.balanceB ) * 0.5 );
    const double blueAmberAxis = balanceStats.balanceB - balanceStats.balanceR;
    const bool hasNeutralBalance = lookAssistHasNeutralBalanceSamples( balanceStats );
    const int tintCap = lookAssistAutoTintCap( scene, processedFloorLiftedBalance );
    const int tempCap = ( scene == LookAssistScene::BrightSun )
                      ? 250
                      : ( processedFloorLiftedBalance ? 420 : 500 );
    const double tintThreshold = processedFloorLiftedBalance ? 6.0 : 10.0;
    const double tintGain = processedFloorLiftedBalance ? 0.55 : 0.65;
    const double tempThreshold = processedFloorLiftedBalance ? 6.0 : 14.0;
    const double tempGain = processedFloorLiftedBalance ? 16.0 : 18.0;

    if( hasNeutralBalance && fabs( magentaGreenAxis ) >= tintThreshold )
    {
        // Positive tint counteracts green casts; negative tint counteracts magenta casts.
        preset.tintDelta = qBound( -tintCap, (int)qRound( magentaGreenAxis * tintGain ), tintCap );
    }

    if( hasNeutralBalance && fabs( blueAmberAxis ) >= tempThreshold )
    {
        // Positive temperature warms blue-heavy clips; negative temperature cools amber-heavy clips.
        preset.temperatureDelta = qBound( -tempCap, (int)qRound( blueAmberAxis * tempGain ), tempCap );
    }

    if( hasNeutralBalance && lowSignalFloorLiftedBalance )
    {
        if( magentaGreenAxis > -4.0 )
            preset.tintDelta = qMax( preset.tintDelta, 4 );
        if( blueAmberAxis <= -6.0 )
        {
            const int warmCastTemperatureDelta =
                qBound( -360,
                        (int)qRound( blueAmberAxis * 22.0 ),
                        -96 );
            preset.temperatureDelta =
                qMin( preset.temperatureDelta, warmCastTemperatureDelta );
        }
    }
    if( hasNeutralBalance
     && processedFloorLiftedBalance
     && magentaGreenAxis > 2.0
     && balanceStats.greenArtifactRatio >= 0.004
     && balanceStats.greenArtifactMeanAxis >= 25.0 )
    {
        const int artifactTintNudge =
            qBound( 0,
                    (int)qRound( balanceStats.greenArtifactMeanAxis * 0.18
                               + balanceStats.greenArtifactRatio * 120.0 ),
                    qMin( 6, tintCap ) );
        preset.tintDelta = qBound( -tintCap,
                                   preset.tintDelta + artifactTintNudge,
                                   tintCap );
    }

    preset.contrast = qBound( -100, preset.contrast, 100 );
    preset.pivot = qBound( 0, preset.pivot, 100 );
    preset.shadows = qBound( -100, preset.shadows, 100 );
    preset.highlights = qBound( -100, preset.highlights, 100 );
    preset.vibrance = qBound( -100, preset.vibrance, 100 );
    return preset;
}

