void MainWindow::recordPresentedFrame( const RenderFrameThread::ReadyFrame &readyFrame,
                                       const PresentationRequestContext &requestContext )
{
    m_lastPresentedRequestSerial = readyFrame.requestSerial;
    m_lastPresentedRequestContext = requestContext;
    m_lastPresentedRequestContextValid = true;
    m_lastPresentedFrameUsedGpuBilinearDebayer = readyFrame.usedGpuBilinearDebayer;
    m_lastPresentedPlaybackScaleFactorActive = readyFrame.playbackScaleFactorActive;
    m_lastPresentedGpuBilinearFallbackReason = readyFrame.gpuBilinearFallbackReason;
    m_lastPresentedGpuBilinearRendererDescription = readyFrame.gpuBilinearRendererDescription;
    m_lastPresentedFrameUsedGpuAmazeDebayer = readyFrame.usedGpuAmazeDebayer;
    m_lastPresentedGpuAmazeFallbackReason = readyFrame.gpuAmazeFallbackReason;
    m_lastPresentedGpuAmazeRendererDescription = readyFrame.gpuAmazeRendererDescription;
    m_lastPresentedDualIsoPreviewHistogramMs = readyFrame.dualIsoPreviewHistogramMs;
    m_lastPresentedDualIsoPreviewRegressionMs = readyFrame.dualIsoPreviewRegressionMs;
    m_lastPresentedDualIsoPreviewRowscaleMs = readyFrame.dualIsoPreviewRowscaleMs;
    m_lastPresentedStageTimingTelemetry = readyFrame.stageTimingTelemetry;

    const bool priorAutoValidatedNoReadback =
        m_playbackQualityAutoCapabilityTracker.validatedNoReadbackObserved();
    const GpuPlaybackPipelineStatus gpuPlaybackPipelineStatus =
        mainWindowGpuPlaybackPipelineStatus(
            requestContext.gpuPreviewPolicy,
            telemetryBoolValue( readyFrame.stageTimingTelemetry,
                                "gpu_playback_recon_used" ),
            telemetryBoolValue( readyFrame.stageTimingTelemetry,
                                "gpu_playback_recon_texture_present_active" ),
            telemetryBoolValue( readyFrame.stageTimingTelemetry,
                                "gpu_playback_recon_texture_present_no_readback_active" ) );
    const bool dualIsoActive =
        ( m_pMlvObject != nullptr )
        && ( llrpGetDualIsoValidity( m_pMlvObject ) != 0 )
        && ui->checkBoxRawFixEnable->isChecked();
    m_playbackQualityAutoCapabilityTracker.notePresentedPipeline(
        gpuPlaybackPipelineStatus == GpuPlaybackPipelineStatus::GpuTextureNoReadback,
        telemetryBoolValue( readyFrame.stageTimingTelemetry,
                            "gpu_playback_recon_texture_present_no_readback_candidate" ),
        dualIsoActive );
    if( ( !priorAutoValidatedNoReadback
       && m_playbackQualityAutoCapabilityTracker.validatedNoReadbackObserved() )
     || m_playbackQualityAutoCapabilityTracker.lastObservationDemotedCapability() )
    {
        updatePlaybackQualityIndicator();
    }
}

bool MainWindow::isFrameSettledForAnalysis( int frameIndex,
                                            uint64_t requestSerialFloor ) const
{
    if( frameIndex < 0 || !m_lastPresentedRequestContextValid ) return false;
    if( m_lastPresentedRequestSerial < requestSerialFloor ) return false;
    if( m_lastPresentedRequestContext.presentationGeneration
        != m_playbackPresentationGeneration.load( std::memory_order_acquire ) )
    {
        return false;
    }
    return static_cast<int>( m_lastPresentedRequestContext.frameNumber ) == frameIndex;
}

bool MainWindow::isLookAssistFrameSettledForAnalysis( int baselineFrame,
                                                      uint64_t requestSerialFloor,
                                                      int *analysisFrame )
{
    if( analysisFrame ) *analysisFrame = baselineFrame;
    if( baselineFrame < 0 || !m_lastPresentedRequestContextValid ) return false;
    if( m_lastPresentedRequestSerial < requestSerialFloor ) return false;
    if( m_lastPresentedRequestContext.presentationGeneration
        != m_playbackPresentationGeneration.load( std::memory_order_acquire ) )
    {
        return false;
    }

    if( m_playbackQualityMode == static_cast<int>( PlaybackQualityMode::Auto ) )
    {
        if( m_playbackQualityAutoDecisionReason
            == PlaybackQualityAutoDecisionReason::WarmupHq )
        {
            ++m_lookAssistAutoWarmupDeferralCount;
            logInteractionEvent(
                QStringLiteral("look_assist.apply.defer_auto_warmup"),
                QStringLiteral("baseline_frame=%1 last_frame=%2 serial=%3 floor=%4 auto_reason=%5 auto_samples=%6 count=%7")
                    .arg( baselineFrame )
                    .arg( static_cast<int>( m_lastPresentedRequestContext.frameNumber ) )
                    .arg( static_cast<qulonglong>( m_lastPresentedRequestSerial ) )
                    .arg( static_cast<qulonglong>( requestSerialFloor ) )
                    .arg( QString::fromLatin1(
                        playbackQualityAutoDecisionReasonName(
                            m_playbackQualityAutoDecisionReason ) ) )
                    .arg( static_cast<qulonglong>(
                        m_playbackQualityAutoDecisionSampleCount ) )
                    .arg( m_lookAssistAutoWarmupDeferralCount ) );
            return false;
        }

        if( analysisFrame )
        {
            *analysisFrame =
                static_cast<int>( m_lastPresentedRequestContext.frameNumber );
        }
        return true;
    }

    return static_cast<int>( m_lastPresentedRequestContext.frameNumber ) == baselineFrame;
}

void MainWindow::finishPresentedFrame( uint64_t displayFrame,
                                       RenderFrameThread::ReadyFrame &readyFrame,
                                       const PresentationRequestContext &requestContext,
                                       const uint8_t *rgb8DisplaySource,
                                       uint8_t underOver,
                                       bool releasePresentedFrameEarly,
                                       QElapsedTimer &prepRegionClock,
                                       qint64 prepRegionStartNs,
                                       double displayStart )
{
    const qint64 prepRegionFinishStartNs = prepRegionClock.nsecsElapsed();
    if( dualIsoWarmupInstrumentationEnabled() )
    {
        if( m_dualIsoWarmupTelemetryPresentationGeneration
            != requestContext.presentationGeneration )
        {
            m_dualIsoWarmupTelemetryPresentationGeneration =
                requestContext.presentationGeneration;
            m_dualIsoWarmupTelemetryPresentedFrames = 0;
        }
        const int presentedIndex =
            m_dualIsoWarmupTelemetryPresentedFrames;
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_presented_index"),
            presentedIndex );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_presented_index_valid"),
            presentedIndex >= 0 );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_presented_warmup_probe_window"),
            presentedIndex >= 0 && presentedIndex < 8 );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_presented_frame"),
            static_cast<qint64>( displayFrame ) );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_presented_request_serial"),
            static_cast<qint64>( readyFrame.requestSerial ) );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_presented_smoke_active"),
            m_playbackSmokeActive );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_presented_play_active"),
            ui->actionPlay->isChecked() );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_presented_position_slider"),
            ui->horizontalSliderPosition->value() );
    }
    const double recordPresentedFrameStart = mlv_stage_timing_now();
    recordPresentedFrame( readyFrame, requestContext );
    mlv_stage_timing_note_elapsed(
        "drawFrameReady.record",
        displayFrame,
        ( mlv_stage_timing_now() - recordPresentedFrameStart ) * 1000.0 );
    const double qualityStart = mlv_stage_timing_now();
    m_lastPresentedFrameColorTelemetry = QJsonObject();
    double headlessPresentedColorAnalysisMs = 0.0;
    if( m_headlessPlaybackProfileActive
     && rgb8DisplaySource
     && readyFrame.renderedImageWidth > 0
     && readyFrame.renderedImageHeight > 0 )
    {
        const double colorAnalysisStart = mlv_stage_timing_now();
        const LookAssistStats frameStats =
            analyzeLookAssistThumbnail( rgb8DisplaySource,
                                        readyFrame.renderedImageWidth,
                                        readyFrame.renderedImageHeight );
        headlessPresentedColorAnalysisMs =
            ( mlv_stage_timing_now() - colorAnalysisStart ) * 1000.0;
        const double visibleGreenAxis =
            frameStats.visibleMeanG
            - ( ( frameStats.visibleMeanR + frameStats.visibleMeanB ) * 0.5 );
        m_lastPresentedFrameColorTelemetry.insert(
            QStringLiteral("presented_green_artifact_ratio"),
            frameStats.greenArtifactRatio );
        m_lastPresentedFrameColorTelemetry.insert(
            QStringLiteral("presented_green_artifact_mean_axis"),
            frameStats.greenArtifactMeanAxis );
        m_lastPresentedFrameColorTelemetry.insert(
            QStringLiteral("presented_green_artifact_samples"),
            frameStats.greenArtifactSamples );
        m_lastPresentedFrameColorTelemetry.insert(
            QStringLiteral("presented_visible_green_axis"),
            visibleGreenAxis );
        m_lastPresentedFrameColorTelemetry.insert(
            QStringLiteral("presented_visible_samples"),
            frameStats.visibleSamples );
        m_lastPresentedFrameColorTelemetry.insert(
            QStringLiteral("presented_dual_iso_core_pattern"),
            readyFrame.dualIsoPattern );
        m_lastPresentedFrameColorTelemetry.insert(
            QStringLiteral("presented_dual_iso_ui_pattern"),
            dualIsoUiPatternIndexFromCorePattern( readyFrame.dualIsoPattern ) );
        m_lastPresentedFrameColorTelemetry.insert(
            QStringLiteral("headless_presented_color_analysis_ms"),
            headlessPresentedColorAnalysisMs );
    }
    updatePlaybackQualityIndicator();
    mlv_stage_timing_note_elapsed(
        "drawFrameReady.quality",
        displayFrame,
        ( mlv_stage_timing_now() - qualityStart ) * 1000.0 );

    const double scopeDispatchStart = mlv_stage_timing_now();
    m_lastDrawFrameReadyScopesMs = 0.0;
    if( ui->actionShowEditArea->isChecked() )
    {
        const double scopes_start = mlv_stage_timing_now();
        bool updateScopesNow = true;
        if( ui->actionPlay->isChecked() )
        {
            const double renderTotalMs =
                telemetryDoubleValue( readyFrame.stageTimingTelemetry,
                                      "render_thread_total_ms" );
            const int baseIntervalMs = playbackScopeUpdateIntervalMs();
            const int intervalMs =
                renderTotalMs > 0.0
                    ? qBound( baseIntervalMs,
                              qRound( renderTotalMs * 1.4 ),
                              500 )
                    : baseIntervalMs;
            updateScopesNow =
                intervalMs <= 0
             || m_playbackScopeLastUpdateTime <= 0.0
             || ( scopes_start - m_playbackScopeLastUpdateTime ) * 1000.0
                >= static_cast<double>( intervalMs );
        }

        if( updateScopesNow )
        {
            bool under = false;
            bool over = false;
            if( ( underOver & 0x01 ) == 0x01 ) under = true;
            if( ( underOver & 0x02 ) == 0x02 ) over = true;

            if( ui->actionShowHistogram->isChecked() )
            {
                ui->labelScope->setScope( const_cast<uint8_t *>( rgb8DisplaySource ),
                                          readyFrame.renderedImageWidth,
                                          readyFrame.renderedImageHeight,
                                          under,
                                          over,
                                          ScopesLabel::ScopeHistogram );
            }
            else if( ui->actionShowWaveFormMonitor->isChecked() )
            {
                ui->labelScope->setScope( const_cast<uint8_t *>( rgb8DisplaySource ),
                                          readyFrame.renderedImageWidth,
                                          readyFrame.renderedImageHeight,
                                          under,
                                          over,
                                          ScopesLabel::ScopeWaveForm );
            }
            else if( ui->actionShowParade->isChecked() )
            {
                ui->labelScope->setScope( const_cast<uint8_t *>( rgb8DisplaySource ),
                                          readyFrame.renderedImageWidth,
                                          readyFrame.renderedImageHeight,
                                          under,
                                          over,
                                          ScopesLabel::ScopeRgbParade);
            }
            else if( ui->actionShowVectorScope->isChecked() )
            {
                ui->labelScope->setScope( const_cast<uint8_t *>( rgb8DisplaySource ),
                                          readyFrame.renderedImageWidth,
                                          readyFrame.renderedImageHeight,
                                          under,
                                          over,
                                          ScopesLabel::ScopeVectorScope );
            }
            m_playbackScopeLastUpdateTime = mlv_stage_timing_now();
            ++m_playbackScopeUpdateCount;
            m_lastDrawFrameReadyScopesMs =
                (m_playbackScopeLastUpdateTime - scopes_start) * 1000.0;
            mlv_stage_timing_note_elapsed("drawFrameReady.scopes", displayFrame, m_lastDrawFrameReadyScopesMs);
        }
        else
        {
            ++m_playbackScopeSkipCount;
        }
    }
    else
    {
        m_playbackScopeLastUpdateTime = 0.0;
    }
    mlv_stage_timing_note_elapsed(
        "drawFrameReady.scope_dispatch",
        displayFrame,
        ( mlv_stage_timing_now() - scopeDispatchStart ) * 1000.0 );

    const double overlay_start = mlv_stage_timing_now();
    if( m_tryToSyncAudio && m_pAudioPlayback && ui->actionAudioOutput->isChecked() && ui->actionPlay->isChecked() && ui->actionDropFrameMode->isChecked() )
    {
        m_tryToSyncAudio = false;
        ++m_playbackAudioSyncRequestCount;
        const double syncNow = mlv_stage_timing_now();
        const int syncFrame = m_newPosDropMode;
        const bool duplicateRecentSync =
            m_lastPlaybackAudioSyncFrame == syncFrame
         && m_lastPlaybackAudioSyncTime > 0.0
         && ( syncNow - m_lastPlaybackAudioSyncTime ) * 1000.0 < 100.0;
        if( duplicateRecentSync )
        {
            ++m_playbackAudioSyncSkippedCount;
        }
        else
        {
            m_lastPlaybackAudioSyncFrame = syncFrame;
            m_lastPlaybackAudioSyncTime = syncNow;
            ++m_playbackAudioSyncAppliedCount;
            m_pAudioPlayback->stop();
            m_pAudioPlayback->jumpToPos( syncFrame );
            m_pAudioPlayback->play();
        }
    }

    drawFrameNumberLabel( static_cast<int>(displayFrame) );
    if( !m_tcModeDuration )
    {
        updateTimeCodeLabelForFrame( static_cast<int>(displayFrame) );
    }

    if( m_zoomTo100Center )
    {
        m_zoomTo100Center = false;
        ui->graphicsView->horizontalScrollBar()->setValue( ( getMlvWidth(m_pMlvObject) * getHorizontalStretchFactor(false) - ui->graphicsView->width() ) / 2 );
        ui->graphicsView->verticalScrollBar()->setValue( ( getMlvHeight(m_pMlvObject) * getVerticalStretchFactor(false) - ui->graphicsView->height() ) / 2 );
    }

    if( m_zoomModeChanged )
    {
        m_zoomModeChanged = false;
        m_pGradientElement->redrawGradientElement( m_pScene->width(),
                                                  m_pScene->height(),
                                                  getMlvWidth( m_pMlvObject ),
                                                  getMlvHeight( m_pMlvObject ) );
    }

    if( ui->toolButtonBadPixelsCrosshairEnable->isChecked()
     && toolButtonBadPixelsCurrentIndex() >= 3
     && ui->checkBoxRawFixEnable->isChecked() )
    {
        BadPixelFileHandler::crossesRedrawAll( m_pMlvObject, &m_pBadPixelCrosses, m_pScene );
        setBadPixelCrosshairVisibility( true );
    }
    else
    {
        setBadPixelCrosshairVisibility( false );
    }

    if( m_playbackStopped == true )
    {
        selectDebayerAlgorithm();
        applyEffectiveDualIsoPlaybackSettings();
        m_playbackStopped = false;
    }

    ui->actionDeleteSelectedClips->setEnabled( true );

    const double overlayEndStageTime = mlv_stage_timing_now();
    m_lastDrawFrameReadyOverlayMs = (overlayEndStageTime - overlay_start) * 1000.0;
    mlv_stage_timing_note_elapsed("drawFrameReady.overlay", displayFrame, m_lastDrawFrameReadyOverlayMs);
    const double drawTotalEndStageTime = mlv_stage_timing_now();
    m_lastDrawFrameReadyTotalMs = (drawTotalEndStageTime - displayStart) * 1000.0;
    if( m_playbackSmokeTimelineTelemetry )
    {
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_draw_end_stage_time"),
            drawTotalEndStageTime );
    }
    mlv_stage_timing_note_elapsed("drawFrameReady.total", displayFrame, m_lastDrawFrameReadyTotalMs);
    if( ui->actionPlay->isChecked()
     && playbackQualityModeIntIsPhase3( m_playbackQualityMode ) )
    {
        if( m_phase3LastPresentedStageTime > 0.0
         && displayStart >= m_phase3LastPresentedStageTime )
        {
            notePhase3PlaybackTime(
                static_cast<int>( ( displayStart - m_phase3LastPresentedStageTime ) * 1000.0 ) );
        }
        m_phase3LastPresentedStageTime = displayStart;
    }
    else
    {
        m_phase3LastPresentedStageTime = 0.0;
    }
    if( ui->actionPlay->isChecked() && m_playbackQualityMode == 2 )
    {
        const PlaybackAutoFastPathDiagnosticMode fastDiagMode =
            playback_auto_fast_path_diag_mode();
        const bool forceFast =
            fastDiagMode == PlaybackAutoFastPathDiagnosticMode::ForceFast;
        const bool suppressFast =
            fastDiagMode == PlaybackAutoFastPathDiagnosticMode::SuppressFast;
        bool hasPresentedInterval = false;
        bool decisionEvaluated = false;
        bool effectiveQualityChanged = false;
        bool autoDecisionTelemetryChanged = false;
        bool cacheInvalidated = false;
        bool coreSettingsApplied = false;
        bool fastDecisionSuppressed = false;
        double presentedIntervalMs = 0.0;
        const int previousScale = m_playbackQualityActiveScale;
        const bool previousHq = m_playbackQualityActiveHq;
        PlaybackQualityAutoDecisionReason originalReason =
            m_playbackQualityAutoDecisionReason;
        PlaybackQualityAutoSampler::Decision decision =
            PlaybackQualityAutoSampler::Decision{
                m_playbackQualityActiveScale,
                m_playbackQualityActiveHq,
                m_playbackQualityAutoDecisionReason,
                m_playbackQualityAutoHeadroomCapability,
                m_playbackQualityAutoDecisionAverageMs,
                m_playbackQualityAutoDecisionBudgetMs,
                m_playbackQualityAutoDecisionSampleCount
            };
        if( m_playbackQualityLastPresentedTime > 0.0
         && displayStart >= m_playbackQualityLastPresentedTime )
        {
            presentedIntervalMs =
                ( displayStart - m_playbackQualityLastPresentedTime ) * 1000.0;
            if( presentedIntervalMs > 0.0 )
            {
                hasPresentedInterval = true;
                m_playbackQualitySampler.recordFrameMs( presentedIntervalMs );
                ++m_playbackQualityFrameCounter;
                if( forceFast
                 || (m_playbackQualityFrameCounter
                     % PlaybackQualityAutoSampler::kSlidingWindow) == 0 )
                {
                    decisionEvaluated = true;
                    const bool dualIsoActive =
                        ( m_pMlvObject != nullptr )
                        && ( llrpGetDualIsoValidity( m_pMlvObject ) != 0 )
                        && ui->checkBoxRawFixEnable->isChecked();
                    const bool sharperHeadroomScaleAllowed =
                        m_playbackQualityAutoCapabilityTracker.sharperHeadroomScaleAllowed();
                    if( forceFast )
                    {
                        const size_t diagnosticSampleCount =
                            m_playbackQualityFrameCounter
                                < PlaybackQualityAutoSampler::kSlidingWindow
                            ? m_playbackQualityFrameCounter
                            : PlaybackQualityAutoSampler::kSlidingWindow;
                        decision = playback_auto_force_fast_decision(
                            m_playbackAutoTargetFps,
                            sharperHeadroomScaleAllowed,
                            presentedIntervalMs,
                            diagnosticSampleCount );
                    }
                    else
                    {
                        decision = m_playbackQualitySampler.decideNextSlot(
                            m_playbackAutoTargetFps,
                            dualIsoActive,
                            mlvPlaybackAggressivePreviewMode() != 0,
                            sharperHeadroomScaleAllowed );
                    }
                    originalReason = decision.reason;
                    if( suppressFast
                     && decision.reason
                        == PlaybackQualityAutoDecisionReason::MissedTargetFast )
                    {
                        decision.scaleFactor = 4;
                        decision.useHqMean23 = true;
                        decision.reason = PlaybackQualityAutoDecisionReason::SteadyHq;
                        fastDecisionSuppressed = true;
                    }
                    effectiveQualityChanged =
                        decision.scaleFactor != m_playbackQualityActiveScale
                     || decision.useHqMean23 != m_playbackQualityActiveHq;
                    autoDecisionTelemetryChanged =
                        decision.reason != m_playbackQualityAutoDecisionReason
                     || decision.averageFrameMs != m_playbackQualityAutoDecisionAverageMs
                     || decision.frameBudgetMs != m_playbackQualityAutoDecisionBudgetMs
                     || decision.sampleCount != m_playbackQualityAutoDecisionSampleCount
                     || decision.sharperHeadroomScaleAllowed
                            != m_playbackQualityAutoHeadroomCapability;
                    m_playbackQualityAutoDecisionReason = decision.reason;
                    m_playbackQualityAutoDecisionAverageMs = decision.averageFrameMs;
                    m_playbackQualityAutoDecisionBudgetMs = decision.frameBudgetMs;
                    m_playbackQualityAutoDecisionSampleCount = decision.sampleCount;
                    m_playbackQualityAutoHeadroomCapability =
                        decision.sharperHeadroomScaleAllowed;
                    if( effectiveQualityChanged )
                    {
                        m_playbackQualityActiveScale = decision.scaleFactor;
                        m_playbackQualityActiveHq = decision.useHqMean23;
                        g_playbackQualityActiveHqMirror.store(
                            m_playbackQualityActiveHq ? 1 : 0,
                            std::memory_order_release );
                        invalidateDisplayPreviewCache();
                        cacheInvalidated = true;
                        m_frameChanged = true;
                        updatePlaybackQualityIndicator();
                        applyEffectiveDualIsoPlaybackSettings();
                        coreSettingsApplied = true;
                    }
                    else if( autoDecisionTelemetryChanged )
                    {
                        updatePlaybackQualityIndicator();
                    }
                }
            }
        }
        if( m_playbackSmokeFrameTelemetry )
        {
            qInfo().noquote()
                << QStringLiteral(
                       "playback_auto.decision session=%1 presented_index=%2 "
                       "display_frame=%3 serial=%4 auto_present_index=%5 "
                       "has_interval=%6 interval_ms=%7 decision_evaluated=%8 "
                       "force_fast=%9 suppress_fast=%10 fast_suppressed=%11 "
                       "diag_mode=%12 auto_target_fps=%13 original_reason=%14 "
                       "final_reason=%15 previous_scale=%16 previous_hq=%17 "
                       "new_scale=%18 new_hq=%19 avg_ms=%20 budget_ms=%21 "
                       "sample_count=%22 effective_changed=%23 "
                       "auto_telemetry_changed=%24 cache_invalidated=%25 "
                       "core_settings_applied=%26" )
                   .arg( static_cast<qulonglong>( m_playbackSmokeSessionId ) )
                   .arg( static_cast<qulonglong>(
                       m_playbackSmokePresentedFrames + 1 ) )
                   .arg( static_cast<qulonglong>( displayFrame ) )
                   .arg( static_cast<qulonglong>( readyFrame.requestSerial ) )
                   .arg( static_cast<qulonglong>( m_playbackQualityFrameCounter ) )
                   .arg( bool01( hasPresentedInterval ) )
                   .arg( presentedIntervalMs, 0, 'f', 3 )
                   .arg( bool01( decisionEvaluated ) )
                   .arg( bool01( forceFast ) )
                   .arg( bool01( suppressFast ) )
                   .arg( bool01( fastDecisionSuppressed ) )
                   .arg( QString::fromLatin1(
                       playback_auto_fast_path_diag_name( fastDiagMode ) ) )
                   .arg( m_playbackAutoTargetFps )
                   .arg( QString::fromLatin1(
                       playbackQualityAutoDecisionReasonName( originalReason ) ) )
                   .arg( QString::fromLatin1(
                       playbackQualityAutoDecisionReasonName( decision.reason ) ) )
                   .arg( previousScale )
                   .arg( bool01( previousHq ) )
                   .arg( decision.scaleFactor )
                   .arg( bool01( decision.useHqMean23 ) )
                   .arg( decision.averageFrameMs, 0, 'f', 3 )
                   .arg( decision.frameBudgetMs, 0, 'f', 3 )
                   .arg( static_cast<qulonglong>( decision.sampleCount ) )
                   .arg( bool01( effectiveQualityChanged ) )
                   .arg( bool01( autoDecisionTelemetryChanged ) )
                   .arg( bool01( cacheInvalidated ) )
                   .arg( bool01( coreSettingsApplied ) );
        }
        m_playbackQualityLastPresentedTime = displayStart;
    }
    else
    {
        m_playbackQualityLastPresentedTime = 0.0;
    }
    notePlayToFirstFramePresentation( displayFrame );
    if( m_pRenderThread && !releasePresentedFrameEarly )
        m_pRenderThread->releasePresentedFrameForRequestSerial( readyFrame.requestSerial );
    m_frameStillDrawing = m_pRenderThread && !m_pRenderThread->isIdle();
    if( ui->actionPlay->isChecked() )
    {
        const bool suppressTailAdvanceAfterGpuTexNrEarlyAdvance =
            telemetryBoolValue(
                readyFrame.stageTimingTelemetry,
                "playback_predictive_gpu_tex_nr_advance_executed" );
        if( suppressTailAdvanceAfterGpuTexNrEarlyAdvance )
        {
            m_playbackFrameAdvancePending = false;
        }
        else if( !m_frameStillDrawing )
        {
            m_skipImmediateTimecodeLabel = true;
            const bool timelineTelemetry = m_playbackSmokeTimelineTelemetry;
            const uint64_t expectedRequestSerial =
                timelineTelemetry ? m_nextRenderRequestSerial : 0;
            const double advance_start = mlv_stage_timing_now();
            if( timelineTelemetry )
            {
                m_playbackTimelineAdvancePending = true;
                m_playbackTimelineExpectedRequestSerial = expectedRequestSerial;
                m_playbackTimelineIssuedRequestSerial = 0;
                m_playbackTimelineSourceRequestSerial = readyFrame.requestSerial;
                m_playbackTimelineSourceFrame = static_cast<uint32_t>( displayFrame );
                m_playbackTimelineAdvanceEarly = false;
                m_playbackTimelinePredictiveGpuTexNr = false;
                m_playbackTimelineAdvanceIssueStageTime = advance_start;
                m_playbackTimelineSourceFrameReadyEmitStageTime =
                    readyFrame.frameReadyEmitStageTime;
                m_playbackTimelineSourceDrawBeginStageTime = displayStart;
            }
            timerFrameEvent();
            const double advance_return = mlv_stage_timing_now();
            m_lastDrawFrameReadyAdvanceMs =
                (advance_return - advance_start) * 1000.0;
            const bool timelineRequestIssued =
                timelineTelemetry
                && m_playbackTimelineIssuedRequestSerial == expectedRequestSerial;
            if( timelineTelemetry )
            {
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_tail_advance_issue_stage_time"),
                    advance_start );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_tail_advance_return_stage_time"),
                    advance_return );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_tail_advance_expected_serial"),
                    static_cast<qint64>( expectedRequestSerial ) );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_tail_advance_issued_serial"),
                    static_cast<qint64>(
                        timelineRequestIssued ? expectedRequestSerial : 0 ) );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_tail_advance_request_issued"),
                    timelineRequestIssued );
            }
            if( timelineTelemetry
             && m_playbackTimelineAdvancePending
             && m_playbackTimelineExpectedRequestSerial == expectedRequestSerial )
            {
                m_playbackTimelineAdvancePending = false;
            }
            mlv_stage_timing_note_elapsed("drawFrameReady.advance",
                                          displayFrame,
                                          m_lastDrawFrameReadyAdvanceMs);
            m_skipImmediateTimecodeLabel = false;
        }
        else
        {
            m_playbackFrameAdvancePending = true;
        }
    }
    const qint64 prepRegionFinishEndNs = prepRegionClock.nsecsElapsed();
    const double prepRegionFinishMs =
        static_cast<double>( prepRegionFinishEndNs - prepRegionFinishStartNs ) / 1000000.0;
    readyFrame.stageTimingTelemetry.insert(
        QStringLiteral("playback_prep_region_finish_ms"),
        prepRegionFinishMs );
    const double prepRegionTotalMs =
        prepRegionStartNs >= 0
            ? static_cast<double>( prepRegionFinishEndNs - prepRegionStartNs ) / 1000000.0
            : 0.0;
    readyFrame.stageTimingTelemetry.insert(
        QStringLiteral("playback_prep_region_total_ms"),
        prepRegionTotalMs );
    const double prepRegionAttributedMs =
        telemetryDoubleValue( readyFrame.stageTimingTelemetry,
                              "playback_prep_region_setup_ms" )
        + telemetryDoubleValue( readyFrame.stageTimingTelemetry,
                                "playback_prep_region_gpu_ms" )
        + telemetryDoubleValue( readyFrame.stageTimingTelemetry,
                                "playback_prep_region_image_ms" )
        + telemetryDoubleValue( readyFrame.stageTimingTelemetry,
                                "playback_prep_region_present_ms" )
        + prepRegionFinishMs;
    readyFrame.stageTimingTelemetry.insert(
        QStringLiteral("playback_prep_region_unattributed_ms"),
        prepRegionTotalMs > prepRegionAttributedMs
            ? prepRegionTotalMs - prepRegionAttributedMs
            : 0.0 );
    m_lastPresentedStageTimingTelemetry = readyFrame.stageTimingTelemetry;
    notePlaybackSmokePresentedFrame( displayFrame, readyFrame, requestContext );
    if( dualIsoWarmupInstrumentationEnabled() )
        ++m_dualIsoWarmupTelemetryPresentedFrames;
    if( interactiveTraceEnabled() )
    {
        logInteractionEvent(
            QStringLiteral("draw_frame_ready.end"),
            QStringLiteral("serial=%1 display_frame=%2 play_checked=%3 position=%4 still_drawing=%5 pending_advance=%6 total_ms=%7")
                .arg( static_cast<qulonglong>( readyFrame.requestSerial ) )
                .arg( static_cast<qulonglong>( displayFrame ) )
                .arg( bool01( ui->actionPlay->isChecked() ) )
                .arg( ui->horizontalSliderPosition->value() )
                .arg( bool01( m_frameStillDrawing ) )
                .arg( bool01( m_playbackFrameAdvancePending ) )
                .arg( m_lastDrawFrameReadyTotalMs, 0, 'f', 3 ),
            true );
    }
    emit frameReady();
    const bool immediateGpuTexNrDrain =
        mlvappGpuTexNrImmediateDrainRequested()
        && !m_gpuTexNrImmediateDrainActive
        && ui->actionPlay->isChecked()
        && m_pRenderThread
        && readyFrame.gpuPlaybackReconTextureNoReadbackCandidate
        && requestContext.gpuPlaybackReconTexturePresentRequested
        && requestContext.gpuPlaybackReconAmazeTexturePresentAdmitted
        && telemetryBoolValue(
            readyFrame.stageTimingTelemetry,
            "render_thread_cpu_amaze_debayer_skipped_for_gpu_tex_nr" )
        && m_pRenderThread->hasGpuTextureNoReadbackReadyFrame();
    if( immediateGpuTexNrDrain )
    {
        const int maxDrainCount = mlvappGpuTexNrImmediateDrainMax();
        const bool gpuTexNrReadyBacklogTelemetry =
            mlvappGpuTexNrReadyBacklogTelemetryRequested();
        m_gpuTexNrImmediateDrainActive = true;
        int drainCount = 0;
        while( drainCount < maxDrainCount )
        {
            if( interactiveTraceEnabled() )
            {
                QString drainMessage =
                    QStringLiteral("display_frame=%1 serial=%2 drain=%3/%4")
                        .arg( static_cast<qulonglong>( displayFrame ) )
                        .arg( static_cast<qulonglong>( readyFrame.requestSerial ) )
                        .arg( drainCount + 1 )
                        .arg( maxDrainCount );
                if( gpuTexNrReadyBacklogTelemetry && m_pRenderThread )
                {
                    drainMessage.append(
                        QStringLiteral(" ready_backlog=%1")
                            .arg( m_pRenderThread
                                      ->gpuTextureNoReadbackReadyFrameCount() ) );
                }
                logInteractionEvent(
                    QStringLiteral("draw_frame_ready.gpu_tex_nr_immediate_drain"),
                    drainMessage,
                    true );
            }
            drawFrameReady();
            ++drainCount;
            if( drainCount >= maxDrainCount
             || !m_pRenderThread
             || !m_pRenderThread->hasGpuTextureNoReadbackReadyFrame() )
            {
                break;
            }
        }
        m_gpuTexNrImmediateDrainActive = false;
    }
}

//Draw the frame when render thread is ready
void MainWindow::drawFrameReady()
{
    const double drawReadyEntryStageTime = mlv_stage_timing_now();
    RenderFrameThread::ReadyFrame readyFrame;
    PresentationRequestContext requestContext;
    bool haveReadyFrame = false;
    const uint64_t activeGeneration =
        m_playbackPresentationGeneration.load( std::memory_order_acquire );
    const int activePlaybackTarget =
        ui->actionDropFrameMode->isChecked()
            ? static_cast<int>( m_newPosDropMode )
            : ui->horizontalSliderPosition->value();
    const bool targetAwareLookaheadAcquire =
        mlvappPlaybackRenderLookaheadFrames() > 0 && ui->actionPlay->isChecked();
    int prunedPlaybackLookaheadBeforeAcquire = 0;
    if( targetAwareLookaheadAcquire && m_pRenderThread && m_pMlvObject && m_fileLoaded )
    {
        const int totalFrames = getMlvFrames( m_pMlvObject );
        if( totalFrames > 0 )
        {
            const int cutInFrame =
                qBound( 0, ui->spinBoxCutIn->value() - 1, totalFrames - 1 );
            const int cutOutFrame =
                qBound( cutInFrame, ui->spinBoxCutOut->value() - 1, totalFrames - 1 );
            prunedPlaybackLookaheadBeforeAcquire =
                m_pRenderThread->prunePlaybackLookaheadOutsideForwardWindow(
                    activePlaybackTarget,
                    activeGeneration,
                    cutInFrame,
                    cutOutFrame,
                    mlvappPlaybackRenderLookaheadFrames(),
                    ui->actionLoop->isChecked() );
            if( prunedPlaybackLookaheadBeforeAcquire > 0 && interactiveTraceEnabled() )
            {
                logInteractionEvent(
                    QStringLiteral("draw_frame_ready.prune_lookahead"),
                    QStringLiteral("target=%1 generation=%2 cut_in=%3 cut_out=%4 depth=%5 loop=%6 pruned=%7")
                        .arg( activePlaybackTarget )
                        .arg( static_cast<qulonglong>( activeGeneration ) )
                        .arg( cutInFrame )
                        .arg( cutOutFrame )
                        .arg( mlvappPlaybackRenderLookaheadFrames() )
                        .arg( bool01( ui->actionLoop->isChecked() ) )
                        .arg( prunedPlaybackLookaheadBeforeAcquire ),
                    true );
            }
        }
    }
    const double drawReadyAfterPruneStageTime = mlv_stage_timing_now();
    if( m_pRenderThread )
    {
        const bool gpuTexNrReadyBacklogTelemetry =
            mlvappGpuTexNrReadyBacklogTelemetryRequested();
        int gpuTexNrReadyBacklogBeforeAcquire = 0;
        if( gpuTexNrReadyBacklogTelemetry )
        {
            gpuTexNrReadyBacklogBeforeAcquire =
                m_pRenderThread->gpuTextureNoReadbackReadyFrameCount();
        }
        const bool latestGpuTexNrReady =
            mlvappGpuTexNrAcquireLatestReadyRequested();
        if( targetAwareLookaheadAcquire )
        {
            haveReadyFrame =
                m_pRenderThread
                    ->acquireOldestGpuTextureNoReadbackReadyFrameForPlaybackTarget(
                        &readyFrame,
                        activePlaybackTarget,
                        activeGeneration );
        }
        else
        {
            haveReadyFrame = latestGpuTexNrReady
                ? m_pRenderThread->acquireLatestGpuTextureNoReadbackReadyFrame( &readyFrame )
                : m_pRenderThread->acquireOldestGpuTextureNoReadbackReadyFrame( &readyFrame );
        }
        if( !targetAwareLookaheadAcquire && latestGpuTexNrReady && !haveReadyFrame )
        {
            haveReadyFrame =
                m_pRenderThread->acquireOldestGpuTextureNoReadbackReadyFrame( &readyFrame );
        }
        if( !haveReadyFrame )
        {
            haveReadyFrame = targetAwareLookaheadAcquire
                ? m_pRenderThread->acquireLatestReadyFrameForPlaybackTarget(
                    &readyFrame,
                    activePlaybackTarget,
                    activeGeneration )
                : m_pRenderThread->acquireLatestReadyFrame( &readyFrame );
        }
        if( haveReadyFrame )
        {
            if( gpuTexNrReadyBacklogTelemetry )
            {
                const int gpuTexNrReadyBacklogAfterAcquire =
                    m_pRenderThread->gpuTextureNoReadbackReadyFrameCount();
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_gpu_tex_nr_ready_backlog_before_acquire"),
                    gpuTexNrReadyBacklogBeforeAcquire );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_gpu_tex_nr_ready_backlog_after_acquire"),
                    gpuTexNrReadyBacklogAfterAcquire );
            }
            if( m_playbackSmokeFrameTelemetry )
            {
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_gpu_tex_nr_acquire_latest_ready_requested"),
                    latestGpuTexNrReady );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_gpu_tex_nr_acquire_mode"),
                    latestGpuTexNrReady
                        ? QStringLiteral("latest_ready_opt_in")
                        : QStringLiteral("oldest_ordered_default") );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_lookahead_pruned_before_acquire"),
                    prunedPlaybackLookaheadBeforeAcquire );
            }
        }
    }
    const double drawReadyAfterAcquireStageTime = mlv_stage_timing_now();
    if( !haveReadyFrame )
    {
        m_frameStillDrawing = m_pRenderThread && !m_pRenderThread->isIdle();
        if( interactiveTraceEnabled() )
        {
            logInteractionEvent(
                QStringLiteral("draw_frame_ready.empty"),
                QStringLiteral("still_drawing=%1 render_idle=%2 play_checked=%3 position=%4")
                    .arg( bool01( m_frameStillDrawing ) )
                    .arg( bool01( m_pRenderThread && m_pRenderThread->isIdle() ) )
                    .arg( bool01( ui->actionPlay->isChecked() ) )
                    .arg( ui->horizontalSliderPosition->value() ),
                true );
        }
        if( !m_frameStillDrawing
         && ui->actionPlay->isChecked()
         && m_playbackFrameAdvancePending )
        {
            m_skipImmediateTimecodeLabel = true;
            const double advance_start = mlv_stage_timing_now();
            timerFrameEvent( true );
            m_lastDrawFrameReadyAdvanceMs =
                ( mlv_stage_timing_now() - advance_start ) * 1000.0;
            mlv_stage_timing_note_elapsed(
                "drawFrameReady.empty_advance",
                static_cast<uint64_t>( ui->horizontalSliderPosition->value() ),
                m_lastDrawFrameReadyAdvanceMs );
            m_skipImmediateTimecodeLabel = false;
        }
        return;
    }

    consumePresentationRequest( readyFrame.requestSerial, nullptr );
    const double drawReadyAfterConsumeStageTime = mlv_stage_timing_now();
    requestContext = readyFrame.presentationContext;
    if( requestContext.presentationGeneration != activeGeneration )
    {
        m_playbackPrepStaleDropCount.fetch_add( 1, std::memory_order_acq_rel );
        m_playbackPrepGenerationDropCount.fetch_add( 1, std::memory_order_acq_rel );
        if( interactiveTraceEnabled() )
        {
            logInteractionEvent(
                QStringLiteral("draw_frame_ready.drop_generation"),
                QStringLiteral("serial=%1 display_frame=%2 request_generation=%3 active_generation=%4 requested_scale=%5 active_scale=%6 rendered=%7x%8 scaled=%9x%10")
                    .arg( static_cast<qulonglong>( readyFrame.requestSerial ) )
                    .arg( static_cast<qulonglong>( readyFrame.frameNumber ) )
                    .arg( static_cast<qulonglong>( requestContext.presentationGeneration ) )
                    .arg( static_cast<qulonglong>( activeGeneration ) )
                    .arg( requestContext.playbackScaleFactor )
                    .arg( readyFrame.playbackScaleFactorActive )
                    .arg( readyFrame.renderedImageWidth )
                    .arg( readyFrame.renderedImageHeight )
                    .arg( readyFrame.playbackScaledWidth )
                    .arg( readyFrame.playbackScaledHeight ),
                true );
        }
        if( m_pRenderThread )
            m_pRenderThread->releasePresentedFrameForRequestSerial( readyFrame.requestSerial );
        m_frameStillDrawing = m_pRenderThread && !m_pRenderThread->isIdle();
        m_frameChanged = true;
        return;
    }

    const uint64_t display_frame = readyFrame.frameNumber;
    if( requestContext.playbackLookaheadRequest )
    {
        const bool targetReached =
            ui->actionPlay->isChecked()
            && static_cast<int>( display_frame ) == activePlaybackTarget;
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_lookahead_request"),
            true );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_lookahead_depth"),
            requestContext.playbackLookaheadDepth );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_lookahead_active_target"),
            activePlaybackTarget );
        if( !targetReached )
        {
            m_playbackPrepStaleDropCount.fetch_add( 1, std::memory_order_acq_rel );
            if( interactiveTraceEnabled() )
            {
                logInteractionEvent(
                    QStringLiteral("draw_frame_ready.drop_lookahead"),
                    QStringLiteral("serial=%1 display_frame=%2 target=%3 origin=%4 depth=%5")
                        .arg( static_cast<qulonglong>( readyFrame.requestSerial ) )
                        .arg( static_cast<qulonglong>( display_frame ) )
                        .arg( activePlaybackTarget )
                        .arg( static_cast<qulonglong>(
                            requestContext.playbackLookaheadOriginFrame ) )
                        .arg( requestContext.playbackLookaheadDepth ),
                    true );
            }
            if( m_pRenderThread )
                m_pRenderThread->releasePresentedFrameForRequestSerial(
                    readyFrame.requestSerial );
            m_frameStillDrawing = m_pRenderThread && !m_pRenderThread->isIdle();
            if( ui->actionPlay->isChecked() && m_playbackFrameAdvancePending )
            {
                QTimer::singleShot( 0, this, [this, display_frame]()
                {
                    if( !ui->actionPlay->isChecked()
                     || !m_playbackFrameAdvancePending )
                    {
                        return;
                    }
                    m_frameStillDrawing =
                        m_pRenderThread && !m_pRenderThread->isIdle();
                    if( m_frameStillDrawing ) return;

                    m_skipImmediateTimecodeLabel = true;
                    const double advance_start = mlv_stage_timing_now();
                    timerFrameEvent();
                    m_lastDrawFrameReadyAdvanceMs =
                        ( mlv_stage_timing_now() - advance_start ) * 1000.0;
                    mlv_stage_timing_note_elapsed(
                        "drawFrameReady.lookahead_drop_advance",
                        display_frame,
                        m_lastDrawFrameReadyAdvanceMs );
                    m_skipImmediateTimecodeLabel = false;
                } );
            }
            return;
        }
    }

    // Forward-only present guard: during forward playback never present a frame older
    // than the one already on screen. A backward-jumping display frame is a stale,
    // out-of-order render (the playback position briefly moved back when this frame was
    // requested) and shows on screen as a "flicker to an older frame". Loop-wrap and
    // scrubbing move the slider position itself backward, so they pass (the position is
    // not still ahead of the last shown frame); paused/scrub (play unchecked) passes too.
    if( ui->actionPlay->isChecked()
     && m_lastPresentedPlaybackFrame >= 0
     && static_cast<long long>( display_frame ) < m_lastPresentedPlaybackFrame
     && static_cast<long long>( ui->horizontalSliderPosition->value() ) >= m_lastPresentedPlaybackFrame )
    {
        m_playbackPrepStaleDropCount.fetch_add( 1, std::memory_order_acq_rel );
        if( interactiveTraceEnabled() )
        {
            logInteractionEvent(
                QStringLiteral("draw_frame_ready.skip_backward"),
                QStringLiteral("display_frame=%1 last_presented=%2 position=%3 serial=%4")
                    .arg( static_cast<qulonglong>( display_frame ) )
                    .arg( static_cast<qlonglong>( m_lastPresentedPlaybackFrame ) )
                    .arg( ui->horizontalSliderPosition->value() )
                    .arg( static_cast<qulonglong>( readyFrame.requestSerial ) ),
                true );
        }
        if( m_pRenderThread )
            m_pRenderThread->releasePresentedFrameForRequestSerial( readyFrame.requestSerial );
        m_frameStillDrawing = m_pRenderThread && !m_pRenderThread->isIdle();
        m_frameChanged = true;
        return;
    }
    m_lastPresentedPlaybackFrame = static_cast<long long>( display_frame );

    /* Round-4 item 3: dispatch the NEXT frame render BEFORE the present work
     * below. The present span runs on this (GUI) thread, so the render
     * thread used to sit starved for its whole duration (the measured
     * ~12-15ms present_pacing band) because the next request was only
     * created in the post-present tail. The frame slots, the request queue,
     * the latest-by-serial acquire and the forward-only guard above already
     * support one frame rendering while another presents; this only moves
     * the existing inline advance ahead of the paint. The tail advance still
     * runs and degrades to m_playbackFrameAdvancePending while the early
     * render is in flight. */
    /* Round-4 item 7b: reset the advance timing HERE, before the early advance
     * runs, instead of in the shared reset block below. When the early advance
     * fires it dispatches the next render and leaves the render thread busy, so
     * the tail advance in finishPresentedFrame does not re-fire; the shared
     * reset below previously zeroed this measurement before the smoke
     * accounting (notePlaybackSmokePresentedFrame) read it as
     * presentRenderSlotReleaseMs, which under-reported the early advance cost
     * and inflated the residual present-pacing band. */
    m_lastDrawFrameReadyAdvanceMs = 0.0;
    const bool predictiveGpuTexNrEarlyAdvance =
        ui->actionPlay->isChecked()
        && readyFrame.gpuPlaybackReconTextureNoReadbackCandidate
        && requestContext.gpuPlaybackReconTexturePresentRequested
        && requestContext.gpuPlaybackReconAmazeTexturePresentAdmitted
        && telemetryBoolValue(
            readyFrame.stageTimingTelemetry,
            "render_thread_cpu_amaze_debayer_skipped_for_gpu_tex_nr" );
    if( m_playbackSmokeFrameTelemetry )
    {
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_predictive_gpu_tex_nr_advance_requested"),
            predictiveGpuTexNrEarlyAdvance );
    }
    const double drawReadyBeforeEarlyAdvanceStageTime = mlv_stage_timing_now();
    bool predictiveGpuTexNrEarlyAdvanceExecuted = false;
    bool predictiveGpuTexNrEarlyAdvancePlaybackEligible = false;
    bool predictiveGpuTexNrEarlyAdvanceRenderIdle = false;
    bool predictiveGpuTexNrEarlyAdvanceSuppressedByIsIdle = false;
    if( ui->actionPlay->isChecked() && m_pRenderThread )
    {
        predictiveGpuTexNrEarlyAdvancePlaybackEligible = true;
        m_frameStillDrawing = !m_pRenderThread->isIdle();
        predictiveGpuTexNrEarlyAdvanceRenderIdle = !m_frameStillDrawing;
        predictiveGpuTexNrEarlyAdvanceSuppressedByIsIdle =
            predictiveGpuTexNrEarlyAdvance && m_frameStillDrawing;
        if( !m_frameStillDrawing )
        {
            m_skipImmediateTimecodeLabel = true;
            const bool timelineTelemetry = m_playbackSmokeTimelineTelemetry;
            const int configuredEarlyAdvanceYieldCount =
                mlvappGpuTexNrYieldAfterEarlyAdvanceCount();
            const bool trackEarlyAdvanceRequest =
                timelineTelemetry || configuredEarlyAdvanceYieldCount > 0;
            const uint64_t expectedRequestSerial =
                trackEarlyAdvanceRequest ? m_nextRenderRequestSerial : 0;
            const double advance_start = mlv_stage_timing_now();
            if( trackEarlyAdvanceRequest )
            {
                m_playbackTimelineAdvancePending = true;
                m_playbackTimelineExpectedRequestSerial = expectedRequestSerial;
                m_playbackTimelineIssuedRequestSerial = 0;
                m_playbackTimelineSourceRequestSerial = readyFrame.requestSerial;
                m_playbackTimelineSourceFrame = static_cast<uint32_t>( display_frame );
                m_playbackTimelineAdvanceEarly = true;
                m_playbackTimelinePredictiveGpuTexNr = predictiveGpuTexNrEarlyAdvance;
                m_playbackTimelineAdvanceIssueStageTime = advance_start;
                m_playbackTimelineSourceFrameReadyEmitStageTime =
                    readyFrame.frameReadyEmitStageTime;
                m_playbackTimelineSourceDrawBeginStageTime = 0.0;
            }
            timerFrameEvent( predictiveGpuTexNrEarlyAdvance );
            const double advance_return = mlv_stage_timing_now();
            m_lastDrawFrameReadyAdvanceMs =
                (advance_return - advance_start) * 1000.0;
            predictiveGpuTexNrEarlyAdvanceExecuted = true;
            const bool timelineRequestIssued =
                trackEarlyAdvanceRequest
                && m_playbackTimelineIssuedRequestSerial == expectedRequestSerial;
            const int earlyAdvanceYieldCount =
                ( timelineRequestIssued && predictiveGpuTexNrEarlyAdvance )
                    ? configuredEarlyAdvanceYieldCount
                    : 0;
            double earlyAdvanceYieldMs = 0.0;
            if( earlyAdvanceYieldCount > 0 )
            {
                const double yieldStart = mlv_stage_timing_now();
                for( int i = 0; i < earlyAdvanceYieldCount; ++i )
                {
                    QThread::yieldCurrentThread();
                }
                earlyAdvanceYieldMs =
                    ( mlv_stage_timing_now() - yieldStart ) * 1000.0;
            }
            if( timelineTelemetry )
            {
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_early_advance_issue_stage_time"),
                    advance_start );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_early_advance_return_stage_time"),
                    advance_return );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_early_advance_expected_serial"),
                    static_cast<qint64>( expectedRequestSerial ) );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_early_advance_issued_serial"),
                    static_cast<qint64>(
                        timelineRequestIssued ? expectedRequestSerial : 0 ) );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_early_advance_request_issued"),
                    timelineRequestIssued );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_early_advance_yield_count"),
                    earlyAdvanceYieldCount );
                readyFrame.stageTimingTelemetry.insert(
                    QStringLiteral("playback_timeline_early_advance_yield_elapsed_ms"),
                    earlyAdvanceYieldMs );
            }
            if( trackEarlyAdvanceRequest
             && m_playbackTimelineAdvancePending
             && m_playbackTimelineExpectedRequestSerial == expectedRequestSerial )
            {
                m_playbackTimelineAdvancePending = false;
            }
            mlv_stage_timing_note_elapsed("drawFrameReady.advance_early",
                                          display_frame,
                                          m_lastDrawFrameReadyAdvanceMs);
            m_skipImmediateTimecodeLabel = false;
        }
    }
    const double drawReadyAfterEarlyAdvanceStageTime = mlv_stage_timing_now();
    readyFrame.stageTimingTelemetry.insert(
        QStringLiteral("playback_predictive_gpu_tex_nr_advance_executed"),
        predictiveGpuTexNrEarlyAdvanceExecuted );
    if( m_playbackSmokeFrameTelemetry )
    {
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_early_advance_decision_stage_time"),
            drawReadyBeforeEarlyAdvanceStageTime );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_early_advance_playback_eligible"),
            predictiveGpuTexNrEarlyAdvancePlaybackEligible );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_early_advance_render_idle_at_decision"),
            predictiveGpuTexNrEarlyAdvanceRenderIdle );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_early_advance_frame_still_drawing_at_decision"),
            predictiveGpuTexNrEarlyAdvancePlaybackEligible
                && !predictiveGpuTexNrEarlyAdvanceRenderIdle );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_early_advance_suppressed_by_isidle"),
            predictiveGpuTexNrEarlyAdvanceSuppressedByIsIdle );
    }

    const double display_start = mlv_stage_timing_now();
    if( m_playbackSmokeTimelineTelemetry )
    {
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_draw_ready_entry_stage_time"),
            drawReadyEntryStageTime );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_draw_ready_after_prune_stage_time"),
            drawReadyAfterPruneStageTime );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_draw_ready_after_acquire_stage_time"),
            drawReadyAfterAcquireStageTime );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_draw_ready_after_consume_stage_time"),
            drawReadyAfterConsumeStageTime );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_draw_ready_before_early_advance_stage_time"),
            drawReadyBeforeEarlyAdvanceStageTime );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_draw_ready_after_early_advance_stage_time"),
            drawReadyAfterEarlyAdvanceStageTime );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_draw_begin_stage_time"),
            display_start );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_current_request_serial"),
            static_cast<qint64>( readyFrame.requestSerial ) );
        readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_timeline_current_frame_ready_emit_stage_time"),
            readyFrame.frameReadyEmitStageTime );
    }
    if( interactiveTraceEnabled() )
    {
        logInteractionEvent(
            QStringLiteral("draw_frame_ready.begin"),
            QStringLiteral("serial=%1 display_frame=%2 play_checked=%3 position=%4 render_idle=%5 requested_scale=%6 active_scale=%7 generation=%8 rendered=%9x%10 scaled=%11x%12")
                .arg( static_cast<qulonglong>( readyFrame.requestSerial ) )
                .arg( static_cast<qulonglong>( display_frame ) )
                .arg( bool01( ui->actionPlay->isChecked() ) )
                .arg( ui->horizontalSliderPosition->value() )
                .arg( bool01( m_pRenderThread && m_pRenderThread->isIdle() ) )
                .arg( requestContext.playbackScaleFactor )
                .arg( readyFrame.playbackScaleFactorActive )
                .arg( static_cast<qulonglong>( requestContext.presentationGeneration ) )
                .arg( readyFrame.renderedImageWidth )
                .arg( readyFrame.renderedImageHeight )
                .arg( readyFrame.playbackScaledWidth )
                .arg( readyFrame.playbackScaledHeight ),
            true );
    }
    m_lastDrawFrameReadyQueueMs = 0.0;
    /* m_lastDrawFrameReadyAdvanceMs is reset above, before the early advance,
     * so its early measurement is not zeroed before the smoke accounting. */
    m_lastDrawFrameReadySceneMs = 0.0;
    m_lastDrawFrameReadyImageMs = 0.0;
    m_lastDrawFrameReadyPresentMs = 0.0;
    m_lastDrawFrameReadyScopesMs = 0.0;
    m_lastDrawFrameReadyOverlayMs = 0.0;
    if( readyFrame.frameReadyEmitStageTime > 0.0
     && display_start >= readyFrame.frameReadyEmitStageTime )
    {
        m_lastDrawFrameReadyQueueMs =
            (display_start - readyFrame.frameReadyEmitStageTime) * 1000.0;
    }
    const bool gpuViewportInstalled = gpuPreviewSurfaceActive();
    const bool zoomFitEnabled = ui->actionZoomFit->isChecked();
    const bool zebrasEnabled = ui->actionShowZebras->isChecked();
    const bool betterResizerEnabled = ui->actionBetterResizer->isChecked();
    const int sourceWidth = readyFrame.renderedImageWidth > 0
        ? readyFrame.renderedImageWidth
        : getMlvWidth( m_pMlvObject );
    const int sourceHeight = readyFrame.renderedImageHeight > 0
        ? readyFrame.renderedImageHeight
        : getMlvHeight( m_pMlvObject );
    const double stretchX = getHorizontalStretchFactor(false);
    const double stretchY = getVerticalStretchFactor(false);
    Qt::TransformationMode mode = Qt::FastTransformation;
    int sceneWidth = sourceWidth;
    int sceneHeight = sourceHeight;
    if( !playbackPolicyActive()
     || ui->actionUseNoneDebayer->isChecked()
     || ui->actionCaching->isChecked() )
    {
        mode = Qt::SmoothTransformation;
    }

    MainWindowGpuPreviewPolicyState gpuPreviewPolicy = requestContext.gpuPreviewPolicy;
    gpuPreviewPolicy.gpuViewportInstalled = gpuViewportInstalled;

    const bool gpu16PreviewActive = mainWindowUsesGpu16PreviewPresentation( gpuPreviewPolicy );
    const bool gpuPreviewProcessingActive = mainWindowUsesGpuPreviewProcessing( gpuPreviewPolicy );
    const bool cpuPreviewProcessingActive =
        requestContext.renderThreadUsingCpuPreviewProcessing
        && requestContext.gpuPreviewProcessingConfig.enabled;
    const bool useGpuImagePresentation = mainWindowUsesGpuImagePresentation( gpuPreviewPolicy );
    const bool useGpuShaderZebras = mainWindowUsesGpuShaderZebraProcessing( gpuPreviewPolicy );
    GpuPreviewProcessingConfig gpuPreviewProcessingConfig =
        (gpuPreviewProcessingActive || cpuPreviewProcessingActive)
            ? requestContext.gpuPreviewProcessingConfig
            : GpuPreviewProcessingConfig();

    m_playbackFrameAdvancePending = false;
    const double scene_start = mlv_stage_timing_now();
    computeDisplaySceneGeometry( sourceWidth,
                                 sourceHeight,
                                 zoomFitEnabled,
                                 stretchX,
                                 stretchY,
                                 &sceneWidth,
                                 &sceneHeight );
    const bool currentFastPlaybackPresentation =
        readyFrame.playbackFastScaleActive
        && zoomFitEnabled
        && mode == Qt::FastTransformation
        && !zebrasEnabled;
    if( currentFastPlaybackPresentation
     && readyFrame.playbackScaledWidth > 0
     && readyFrame.playbackScaledHeight > 0 )
    {
        sceneWidth =
            std::max( 1, qRound( static_cast<double>( readyFrame.playbackScaledWidth )
                                 / qMax( 1.0, devicePixelRatioF() ) ) );
        sceneHeight =
            std::max( 1, qRound( static_cast<double>( readyFrame.playbackScaledHeight )
                                 / qMax( 1.0, devicePixelRatioF() ) ) );
    }

    if( m_lastDisplaySceneWidth != sceneWidth
     || m_lastDisplaySceneHeight != sceneHeight )
    {
        m_pScene->setSceneRect( 0, 0, sceneWidth, sceneHeight );
        m_lastDisplaySceneWidth = sceneWidth;
        m_lastDisplaySceneHeight = sceneHeight;
    }
    m_lastDrawFrameReadySceneMs = (mlv_stage_timing_now() - scene_start) * 1000.0;
    mlv_stage_timing_note_elapsed("drawFrameReady.scene", display_frame, m_lastDrawFrameReadySceneMs);

    const int dualIsoToolMode = toolButtonDualIsoCurrentIndex();
    if( dualIsoToolMode > 0 )
    {
        ACTIVE_RECEIPT->setDualIsoAutoCorrected( 1 );
        int cachedPattern = m_dualIsoPlaybackUiCacheValid
            ? m_dualIsoPlaybackUiCache.pattern
            : -2;

        if( readyFrame.dualIsoPattern < 0 )
        {
            const int uiPattern =
                dualIsoUiPatternIndexFromCorePattern( readyFrame.dualIsoPattern );
            const bool dualIsoWidgetCacheHit =
                m_dualIsoPlaybackUiCacheValid
             && m_dualIsoPlaybackUiCache.toolMode == dualIsoToolMode
             && m_dualIsoPlaybackUiCache.pattern == uiPattern
             && m_dualIsoPlaybackUiCache.autoCorrection == readyFrame.dualIsoAutoCorrection
             && m_dualIsoPlaybackUiCache.evCorrection == readyFrame.dualIsoEvCorrection
             && m_dualIsoPlaybackUiCache.blackDelta == readyFrame.dualIsoBlackDelta;
            if( !dualIsoWidgetCacheHit )
            {
                ui->DualIsoPatternComboBox->blockSignals( true );
                ui->DualIsoPatternComboBox->setCurrentIndex( uiPattern );
                ui->DualIsoPatternComboBox->blockSignals( false );
            }
            ACTIVE_RECEIPT->setDualIsoPattern( uiPattern );
            cachedPattern = uiPattern;
        }

        if( dualIsoToolMode == 1 && readyFrame.dualIsoAutoCorrection < 0 )
        {
            const bool dualIsoWidgetCacheHit =
                m_dualIsoPlaybackUiCacheValid
             && m_dualIsoPlaybackUiCache.toolMode == dualIsoToolMode
             && m_dualIsoPlaybackUiCache.autoCorrection == readyFrame.dualIsoAutoCorrection
             && m_dualIsoPlaybackUiCache.evCorrection == readyFrame.dualIsoEvCorrection
             && m_dualIsoPlaybackUiCache.blackDelta == readyFrame.dualIsoBlackDelta;
            if( !dualIsoWidgetCacheHit && readyFrame.dualIsoEvCorrection != 1.0 )
            {
                ui->horizontalSliderDualIsoEvCorrection->blockSignals( true );
                ui->horizontalSliderDualIsoEvCorrection->setValue( (readyFrame.dualIsoEvCorrection * 200) - 0.5 );
                ui->horizontalSliderDualIsoEvCorrection->blockSignals( false );
                ui->DualIsoEvCorrectionVal->setText( QString("%1").arg( readyFrame.dualIsoEvCorrection, 0, 'f', 2 ) );
            }

            if( !dualIsoWidgetCacheHit && readyFrame.dualIsoBlackDelta != -1 )
            {
                ui->horizontalSliderDualIsoBlackDelta->blockSignals( true );
                ui->horizontalSliderDualIsoBlackDelta->setValue( readyFrame.dualIsoBlackDelta );
                ui->horizontalSliderDualIsoBlackDelta->blockSignals( false );
                ui->DualIsoBlackDeltaVal->setText( QString("%1").arg( readyFrame.dualIsoBlackDelta ) );
            }

            m_dualIsoPlaybackUiCache.toolMode = dualIsoToolMode;
            m_dualIsoPlaybackUiCache.pattern = cachedPattern;
            m_dualIsoPlaybackUiCache.autoCorrection = readyFrame.dualIsoAutoCorrection;
            m_dualIsoPlaybackUiCache.evCorrection = readyFrame.dualIsoEvCorrection;
            m_dualIsoPlaybackUiCache.blackDelta = readyFrame.dualIsoBlackDelta;
            m_dualIsoPlaybackUiCacheValid = true;
        }
        else
        {
            m_dualIsoPlaybackUiCache.toolMode = dualIsoToolMode;
            m_dualIsoPlaybackUiCache.pattern = cachedPattern;
            m_dualIsoPlaybackUiCache.autoCorrection = readyFrame.dualIsoAutoCorrection;
            m_dualIsoPlaybackUiCache.evCorrection = readyFrame.dualIsoEvCorrection;
            m_dualIsoPlaybackUiCache.blackDelta = readyFrame.dualIsoBlackDelta;
            m_dualIsoPlaybackUiCacheValid = true;
        }
    }

    const int devicePixelRatioMilli =
        static_cast<int>( devicePixelRatioF() * 1000.0 + 0.5 );
    const int transformationMode = (mode == Qt::SmoothTransformation) ? 1 : 0;
    const bool displayPreviewCachingAllowed = !playbackPolicyActive();
    GpuDisplayViewport::PresentationOptions gpuPresentationOptions =
        requestContext.gpuPresentationOptions;
    gpuPresentationOptions.showZebras = gpuPreviewPolicy.zebrasEnabled;
    if( gpuPreviewProcessingActive )
    {
        gpuPresentationOptions.previewProcessing = gpuPreviewProcessingConfig;
    }

    PlaybackPrepTask task;
    task.readyFrame = readyFrame;
    task.requestContext = requestContext;
    task.requestSerial = readyFrame.requestSerial;
    task.presentationGeneration = requestContext.presentationGeneration;
    task.displayStart = display_start;
    task.displayFrame = display_frame;
    task.stretchX = stretchX;
    task.stretchY = stretchY;
    const size_t sourceImageBytes =
        (sourceWidth > 0 && sourceHeight > 0)
            ? static_cast<size_t>( sourceWidth ) * static_cast<size_t>( sourceHeight ) * 3u
            : 0;
    task.sourceImage = readyFrame.rawImage8;
    task.sourceImageSize = sourceImageBytes;
    task.scopeSourceImage = task.sourceImage;
    task.scopeSourceImageSize = sourceImageBytes;
    const size_t sourceImage16Bytes =
        (sourceWidth > 0 && sourceHeight > 0)
            ? static_cast<size_t>( sourceWidth ) * static_cast<size_t>( sourceHeight ) * 3u
              * sizeof( uint16_t )
            : 0;
    const size_t readyFrameRawImage16Bytes =
        readyFrame.rawImage16Words * sizeof( uint16_t );
    task.sourceImage16 = readyFrame.rawImage16;
    task.sourceImage16Size = readyFrameRawImage16Bytes;
    task.sourceWidth = sourceWidth;
    task.sourceHeight = sourceHeight;
    task.sceneWidth = sceneWidth;
    task.sceneHeight = sceneHeight;
    task.transformationMode = transformationMode;
    task.devicePixelRatioMilli = devicePixelRatioMilli;
    task.gpu16PreviewActive = gpu16PreviewActive;
    task.gpuPreviewProcessingActive = gpuPreviewProcessingActive;
    task.cpuPreviewProcessingActive = cpuPreviewProcessingActive;
    task.useGpuImagePresentation = useGpuImagePresentation;
    task.useGpuShaderZebras = useGpuShaderZebras;
    task.zoomFitEnabled = zoomFitEnabled;
    task.zebrasEnabled = zebrasEnabled;
    task.betterResizerEnabled = betterResizerEnabled;
    task.displayPreviewCachingAllowed = displayPreviewCachingAllowed;
    task.playbackFastScaleActive = readyFrame.playbackFastScaleActive;
    task.gpuPresentationOptions = gpuPresentationOptions;
    task.enqueueTime = mlv_stage_timing_now();
    task.preEnqueueMs =
        ( display_start > 0.0 && task.enqueueTime >= display_start )
            ? ( task.enqueueTime - display_start ) * 1000.0
            : 0.0;
    task.gpuAmazeTextureRawFrame = readyFrame.gpuAmazeTextureRawFrame;
    task.gpuAmazeTextureRawFrameSize = readyFrame.gpuAmazeTextureRawFrameSize;
    task.gpuPlaybackReconTextureBayerFrame =
        readyFrame.gpuPlaybackReconTextureBayerFrame;
    task.gpuPlaybackReconTextureBayerFrameSize =
        readyFrame.gpuPlaybackReconTextureBayerFrameSize;
    task.gpuPlaybackReconTextureInputBayerFrame =
        readyFrame.gpuPlaybackReconTextureInputBayerFrame;
    task.gpuPlaybackReconTextureInputBayerFrameSize =
        readyFrame.gpuPlaybackReconTextureInputBayerFrameSize;
    task.gpuPlaybackReconTextureRetainedDeviceBayer16 =
        readyFrame.gpuPlaybackReconTextureRetainedDeviceBayer16;
    task.gpuPlaybackReconTextureRetainedDeviceWidth =
        readyFrame.gpuPlaybackReconTextureRetainedDeviceWidth;
    task.gpuPlaybackReconTextureRetainedDeviceHeight =
        readyFrame.gpuPlaybackReconTextureRetainedDeviceHeight;
    task.gpuPlaybackReconTextureRetainedDeviceToken =
        readyFrame.gpuPlaybackReconTextureRetainedDeviceToken;
    task.gpuPlaybackReconTextureState =
        readyFrame.gpuPlaybackReconTextureState;
    const size_t borrowedSourceImageBytes =
        (sourceImageBytes > 0 && readyFrame.rawImage8) ? sourceImageBytes : 0;
    const size_t playbackScaledImageBytes =
        (readyFrame.playbackScaledWidth > 0 && readyFrame.playbackScaledHeight > 0)
            ? static_cast<size_t>(
                  readyFrame.playbackScaledBytesPerLine > 0
                      ? readyFrame.playbackScaledBytesPerLine
                      : readyFrame.playbackScaledWidth * 3 )
              * static_cast<size_t>( readyFrame.playbackScaledHeight )
            : 0;
    const size_t borrowedPlaybackScaledImageBytes =
        (playbackScaledImageBytes > 0 && readyFrame.playbackScaledImage8)
            ? playbackScaledImageBytes
            : 0;
    const auto notePlaybackPrepOwnershipTelemetry =
        [&task, borrowedSourceImageBytes, borrowedPlaybackScaledImageBytes]()
    {
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_owned_rgb8_bytes"),
            static_cast<qint64>( task.ownedSourceImage.size() ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_owned_rgb16_bytes"),
            static_cast<qint64>( task.ownedSourceImage16.size() * sizeof( uint16_t ) ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_owned_amaze_texture_raw_bytes"),
            static_cast<qint64>( task.ownedGpuAmazeTextureRawFrame.size() * sizeof( float ) ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_owned_gpu_playback_recon_texture_bayer_bytes"),
            static_cast<qint64>( task.ownedGpuPlaybackReconTextureBayerFrame.size() * sizeof( uint16_t ) ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_owned_gpu_playback_recon_texture_input_bytes"),
            static_cast<qint64>( task.ownedGpuPlaybackReconTextureInputBayerFrame.size() * sizeof( uint16_t ) ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_owned_scaled_rgb8_bytes"),
            static_cast<qint64>( task.ownedPlaybackScaledImage8.size() ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_borrowed_rgb8_bytes"),
            static_cast<qint64>( borrowedSourceImageBytes ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_borrowed_scaled_rgb8_bytes"),
            static_cast<qint64>( borrowedPlaybackScaledImageBytes ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_gpu_tex_nr_owned_input_for_early_release"),
            !task.ownedGpuPlaybackReconTextureInputBayerFrame.empty() );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_gpu_tex_nr_retained_device_token"),
            static_cast<qint64>( task.gpuPlaybackReconTextureRetainedDeviceToken ) );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_gpu_tex_nr_release_before_present"),
            false );
        task.readyFrame.stageTimingTelemetry.insert(
            QStringLiteral("playback_prep_pre_enqueue_ms"),
            task.preEnqueueMs );
    };

    const bool gpuTexNrInlineHostInputAvailable =
        readyFrame.gpuPlaybackReconTextureInputBayerFrame
        && readyFrame.gpuPlaybackReconTextureInputBayerFrameSize > 0;
    const bool gpuTexNrInlineRetainedDeviceAvailable =
        readyFrame.gpuPlaybackReconTextureRetainedDeviceBayer16
        && readyFrame.gpuPlaybackReconTextureRetainedDeviceWidth == sourceWidth
        && readyFrame.gpuPlaybackReconTextureRetainedDeviceHeight == sourceHeight
        && readyFrame.gpuPlaybackReconTextureRetainedDeviceToken != 0;
    const bool gpuTexNrInlineStateMatches =
        readyFrame.gpuPlaybackReconTextureState.valid
        && readyFrame.gpuPlaybackReconTextureState.width == sourceWidth
        && readyFrame.gpuPlaybackReconTextureState.height == sourceHeight;
    const bool inlineGpuPlaybackReconTextureNoReadbackPrep =
        ui->actionPlay->isChecked()
        && readyFrame.gpuPlaybackReconTextureNoReadbackCandidate
        && requestContext.gpuPlaybackReconTexturePresentRequested
        && requestContext.gpuPlaybackReconAmazeTexturePresentAdmitted
        && gpuTexNrInlineStateMatches
        && ( gpuTexNrInlineHostInputAvailable || gpuTexNrInlineRetainedDeviceAvailable );
    task.readyFrame.stageTimingTelemetry.insert(
        QStringLiteral("playback_prep_gpu_tex_nr_inline_host_input_available"),
        gpuTexNrInlineHostInputAvailable );
    task.readyFrame.stageTimingTelemetry.insert(
        QStringLiteral("playback_prep_gpu_tex_nr_inline_retained_device_available"),
        gpuTexNrInlineRetainedDeviceAvailable );
    const bool inlineFastPlaybackPrep =
        ui->actionPlay->isChecked()
        && ( inlineGpuPlaybackReconTextureNoReadbackPrep
          || ( task.playbackFastScaleActive
            && task.zoomFitEnabled
            && task.transformationMode == 0
            && !task.zebrasEnabled
            && !task.useGpuImagePresentation
            && !task.displayPreviewCachingAllowed
            && task.readyFrame.playbackScaledImage8
            && task.readyFrame.playbackScaledWidth > 0
            && task.readyFrame.playbackScaledHeight > 0 ) );
    task.readyFrame.stageTimingTelemetry.insert(
        QStringLiteral("playback_prep_gpu_tex_nr_inline_present"),
        inlineGpuPlaybackReconTextureNoReadbackPrep );
    task.readyFrame.stageTimingTelemetry.insert(
        QStringLiteral("playback_prep_inline_present"),
        inlineFastPlaybackPrep );

    if( inlineFastPlaybackPrep )
    {
        notePlaybackPrepOwnershipTelemetry();
        m_latestRequestedSerial.store( task.requestSerial, std::memory_order_release );
        if( inlineGpuPlaybackReconTextureNoReadbackPrep )
        {
            PlaybackPrepResult result;
            result.task = std::move( task );
            result.task.rebindOwnedImagePointers();
            result.preparedWidth = sourceWidth;
            result.preparedHeight = sourceHeight;
            result.task.readyFrame.stageTimingTelemetry.insert(
                QStringLiteral("gpu_playback_recon_amaze_texture_present_prep_passthrough"),
                true );
            result.imageBuildMs =
                ( mlv_stage_timing_now() - result.task.enqueueTime ) * 1000.0;
            result.workerQueueMs = 0.0;
            result.workerTotalMs = result.imageBuildMs;
            result.resultReadyTime = mlv_stage_timing_now();
            presentPlaybackPreparedFrame( result );
            return;
        }
        PlaybackPrepResult result = buildPlaybackPrepResult( task );
        result.workerQueueMs = 0.0;
        result.workerTotalMs = result.imageBuildMs;
        result.resultReadyTime = mlv_stage_timing_now();
        presentPlaybackPreparedFrame( result );
        return;
    }

    const bool needsOwnedRgb16 =
        gpu16PreviewActive
        || gpuPreviewProcessingActive
        || cpuPreviewProcessingActive
        || readyFrame.outputMode != RenderFrameThread::OutputProcessed8;
    if( needsOwnedRgb16
     && sourceImage16Bytes > 0
     && readyFrame.rawImage16
     && readyFrameRawImage16Bytes >= sourceImage16Bytes )
    {
        const size_t sourceImage16Words = sourceImage16Bytes / sizeof( uint16_t );
        task.ownedSourceImage16.assign( readyFrame.rawImage16,
                                        readyFrame.rawImage16 + sourceImage16Words );
    }
    if( readyFrame.gpuAmazeTexturePresentCandidate
     && readyFrame.gpuAmazeTextureRawFrame
     && readyFrame.gpuAmazeTextureRawFrameSize > 0 )
    {
        task.ownedGpuAmazeTextureRawFrame.assign(
            readyFrame.gpuAmazeTextureRawFrame,
            readyFrame.gpuAmazeTextureRawFrame + readyFrame.gpuAmazeTextureRawFrameSize );
    }
    if( readyFrame.gpuPlaybackReconTexturePresentCandidate
     && readyFrame.gpuPlaybackReconTextureBayerFrame
     && readyFrame.gpuPlaybackReconTextureBayerFrameSize > 0 )
    {
        task.ownedGpuPlaybackReconTextureBayerFrame.assign(
            readyFrame.gpuPlaybackReconTextureBayerFrame,
            readyFrame.gpuPlaybackReconTextureBayerFrame
                + readyFrame.gpuPlaybackReconTextureBayerFrameSize );
    }
    if( readyFrame.gpuPlaybackReconTextureNoReadbackCandidate
     && readyFrame.gpuPlaybackReconTextureInputBayerFrame
     && readyFrame.gpuPlaybackReconTextureInputBayerFrameSize > 0 )
    {
        task.ownedGpuPlaybackReconTextureInputBayerFrame.assign(
            readyFrame.gpuPlaybackReconTextureInputBayerFrame,
            readyFrame.gpuPlaybackReconTextureInputBayerFrame
                + readyFrame.gpuPlaybackReconTextureInputBayerFrameSize );
    }
    task.rebindOwnedImagePointers();
    notePlaybackPrepOwnershipTelemetry();

    enqueuePlaybackPrepTask( task );
    return;

}

//Paintmode for gradient enabled/disabled
void MainWindow::on_toolButtonGradientPaint_toggled(bool checked)
{
    if( !checked )
    {
        ui->graphicsView->setCrossCursorActive( false ); // has to be done first
        ui->graphicsView->setDragMode( QGraphicsView::ScrollHandDrag );
        m_pGradientElement->gradientGraphicsElement()->show();
    }
    else
    {
        ui->toolButtonBadPixelsSearchMethodEdit->setChecked( false );
        m_pGradientElement->gradientGraphicsElement()->hide();
        ui->graphicsView->setDragMode( QGraphicsView::NoDrag );
        ui->graphicsView->setCrossCursorActive( true ); // has to be done last
    }
    m_pScene->setGradientAdjustment( checked );
}

//Gradient Enable checked/unchecked
void MainWindow::on_checkBoxGradientEnable_toggled(bool checked)
{
    if( checked && ui->groupBoxLinearGradient->isChecked() ) m_pGradientElement->gradientGraphicsElement()->show();
    else m_pGradientElement->gradientGraphicsElement()->hide();

    processingSetGradientEnable( m_pProcessingObject, checked );

    m_frameChanged = true;
}

//The gradient startPoint X has changed
void MainWindow::on_spinBoxGradientX_valueChanged(int arg1)
{
    m_pGradientElement->gradientGraphicsElement()->blockSignals( true );
    m_pGradientElement->setStartPos( arg1, ui->spinBoxGradientY->value() );
    m_pGradientElement->redrawGradientElement( m_pScene->width(),
                                               m_pScene->height(),
                                               getMlvWidth( m_pMlvObject ),
                                               getMlvHeight( m_pMlvObject ) );
    m_pGradientElement->gradientGraphicsElement()->blockSignals( false );

    //Send to processing module
    setGradientMask();
}

